          const structuredSystemPrompt = adocBuildSystemPrompt(ragCtx, docCtx, plan, clarityNote, { forStructuredTool: true });
          _struct = await adocGenerateStructuredDocument(_structuredAttemptKind, text, plan, ragResult, structuredSystemPrompt, workerUrl, typingId);
