          console.log('[UX-8A.1] Document structuré (' + _structuredKindLabel + ') rendu avec succès — QC bloquant:', _rendered.qc.blocking.length);
          if (adocExchangeCount % 4 === 0) adocAccumulateSessionContext(plan, _struct.doc.title).catch(()=>{});
