  window.adocKvTherapistIdChange = function(val) {
    adocKvTherapistId = val.trim() || null;
    try {
      if (adocKvTherapistId) localStorage.setItem('adoc_therapist_id', adocKvTherapistId);
      else                   localStorage.removeItem('adoc_therapist_id');
    } catch {}
  };
  (function() {
    try {
      const saved = localStorage.getItem('adoc_therapist_id');
      if (saved) {
        adocKvTherapistId = saved;
        const el = document.getElementById('adoc-kv-therapist-id');
        if (el) el.value = saved;
      }
    } catch {}
  })();
  window.adocKvPatientIdChange = function(val) {
    adocKvPatientId = val.trim() || null;
    document.getElementById('adoc-kv-status').textContent =
      adocKvPatientId ? `ID : ${adocKvPatientId}` : '';
    document.getElementById('adoc-kv-history').style.display = 'none';
    adocKvHistory = [];
  };

  window.adocKvLoad = async function() {
    if (!adocKvPatientId) {
      document.getElementById('adoc-kv-status').innerHTML = adocIconSvg('icon-warning') + ' Saisir un ID patient';
      return;
    }
    const statusEl = document.getElementById('adoc-kv-status');
    statusEl.innerHTML = adocIconSvg('icon-progress') + ' Chargement…';
    try {
      const resp = await fetch(adocGetWorkerUrl() + '/session-load', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-API-Key': adocGetApiKey() },
        body: JSON.stringify({ patientId: adocKvPatientId, ...(adocKvTherapistId ? { therapistId: adocKvTherapistId } : {}) })
      });
      // Audit systémique (Priorité 3) — un statut HTTP en erreur était traité comme "aucune
      // séance enregistrée" (data.found resterait falsy sur un corps d'erreur), masquant une
      // vraie panne serveur derrière un message qui laisse croire qu'il n'y a simplement
      // jamais rien eu à charger.
      if (!resp.ok) {
        statusEl.innerHTML = adocIconSvg('icon-error') + ' Impossible de charger la séance — réessayez';
        return;
      }
      const data = await resp.json();
      if (!data.found || !data.history?.length) {
        statusEl.innerHTML = adocIconSvg('icon-empty') + ' Aucune séance enregistrée';
        adocKvHistory = [];
        document.getElementById('adoc-kv-history').style.display = 'none';
        return;
      }
      adocKvHistory = data.history;
      statusEl.innerHTML = adocIconSvg('icon-verify') + ` ${data.history.length} séance(s) chargée(s)`;
      // Afficher résumé dans la sidebar
      const histEl = document.getElementById('adoc-kv-history');
      histEl.style.display = 'block';
      histEl.innerHTML = data.history.slice(0, 3).map(s =>
        `<div style="margin-bottom:6px;padding:5px 7px;background:var(--terracotta-100);border-radius:4px;font-size:10px;">
          <span style="font-weight:600;color:var(--terracotta-700);">${adocEsc(s.date)}</span><br>
          ${adocEsc(s.summary.substring(0, 120))}${s.summary.length > 120 ? '…' : ''}
        </div>`
      ).join('');
    } catch(e) {
      statusEl.innerHTML = adocIconSvg('icon-error') + ' Erreur : ' + adocEsc(e.message);
    }
  };

  window.adocKvSaveNow = async function() {
    await adocKvAutoSave(true);
  };

  async function adocKvAutoSave(force = false) {
    if (!adocKvPatientId) return;
    const exchanges = adocConversations.filter(m => m.role === 'user');
    if (!force && exchanges.length < 2) return; // Trop peu d'échanges

    const statusEl = document.getElementById('adoc-kv-status');
    if (statusEl) statusEl.innerHTML = adocIconSvg('icon-download') + ' Résumé en cours…';

    // Demander à Haiku de résumer la session
    const recent = adocConversations.slice(-12).map(m =>
      (m.role === 'user' ? 'Thérapeute : ' : 'CC : ') + m.content.substring(0, 300)
    ).join('\n');

    const summaryPayload = {
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 300,
      messages: [{
        role: 'user',
        content: `Résume cette session thérapeutique en 150 mots max, en 3 parties : (1) Sujet principal traité, (2) Concepts/outils cliniques mobilisés, (3) Points importants à retenir pour la prochaine séance. Sois concis et factuel.\n\nSession :\n${recent}`
      }]
    };

    try {
      const resp = await fetch(adocGetWorkerUrl(), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-API-Key': adocGetApiKey() },
        // Audit systémique (Priorité 3) — contrat rompu corrigé : handleAnthropicProxy exige
        // { payload: ... } à la racine (400 "Missing payload" sinon) ; ce payload était envoyé
        // nu depuis toujours ici, donc CETTE requête échouait systématiquement en silence (la
        // réponse d'erreur JSON n'a pas de champ .content, le résumé de repli générique était
        // alors sauvegardé comme si c'était un vrai résumé de session, dans TOUS les cas).
        body: JSON.stringify({ payload: summaryPayload })
      });
      if (!resp.ok) {
        // Ne jamais enregistrer un résumé de repli générique comme s'il s'agissait d'un vrai
        // résumé — on abandonne proprement plutôt que de persister un texte creux dans KV.
        if (statusEl) statusEl.innerHTML = adocIconSvg('icon-error') + ' Résumé automatique indisponible — séance non sauvegardée';
        return;
      }
      const data = await resp.json();
      const summary = data.content?.[0]?.text || 'Session sans résumé automatique.';

      // Sauvegarder dans KV
      const saveResp = await fetch(adocGetWorkerUrl() + '/session-save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-API-Key': adocGetApiKey() },
        body: JSON.stringify({ patientId: adocKvPatientId, summary, ...(adocKvTherapistId ? { therapistId: adocKvTherapistId } : {}) })
      });
      if (!saveResp.ok) {
        // Ne jamais afficher un message de succès trompeur ("Sauvegardé (undefined séance(s))")
        // sur un échec serveur silencieux.
        if (statusEl) statusEl.innerHTML = adocIconSvg('icon-error') + ' Sauvegarde échouée';
        return;
      }
      const saveData = await saveResp.json();
      if (statusEl) statusEl.innerHTML = adocIconSvg('icon-verify') + ` Sauvegardé (${saveData.sessions} séance(s))`;
      // Mettre à jour l'historique local
      adocKvHistory.unshift({ date: new Date().toISOString().slice(0, 10), summary });
      if (adocKvHistory.length > 10) adocKvHistory = adocKvHistory.slice(0, 10);
    } catch(e) {
      if (statusEl) statusEl.innerHTML = adocIconSvg('icon-error') + ' Sauvegarde échouée';
    }
  };

  // ── P2-3 : Affichage coût estimé ──────────────────────────────────────────
  // Tarifs approximatifs en € (mars 2026) — Sonnet 4 / Opus 4
  const COST_RATES = {
    'claude-sonnet-4-6': { in: 0.000003,   out: 0.000015   },  // $3/$15 per Mtok
    'claude-opus-4-6':   { in: 0.000005,   out: 0.000025   },  // $5/$25 per Mtok
    'claude-haiku-4-5-20251001':  { in: 0.00000025, out: 0.00000125 },  // $0.25/$1.25 per Mtok
    'default':                    { in: 0.000003,   out: 0.000015   },
  };
  const EUR_RATE = 0.92; // 1 USD ≈ 0.92 EUR approximatif

  function adocShowCost(msgId, usage) {
    if (!msgId || !usage) return;
    const msgEl = document.getElementById(msgId);
    if (!msgEl) return;
    const model   = window._adocCurrentModel || MODEL;
    const rates   = COST_RATES[model] || COST_RATES['default'];
    const costUsd = (usage.input * rates.in) + (usage.output * rates.out);
    const costEur = costUsd * EUR_RATE;
    adocTotalCost += costEur;

    // Supprimer un éventuel footer précédent
    const old = msgEl.querySelector('.adoc-cost-footer');
    if (old) old.remove();

    const footer = document.createElement('div');
    footer.className = 'adoc-cost-footer adoc-dev-only'; // Phase UX-2A.2 — tokens/coût : mode développeur uniquement
    footer.style.cssText = 'font-size:10px;color:var(--muted);margin-top:4px;padding:2px 8px;text-align:right;opacity:0.8;';
    footer.innerHTML =
      `<span title="Input: ${usage.input.toLocaleString()} tokens · Output: ${usage.output.toLocaleString()} tokens">` +
      `${(usage.input + usage.output).toLocaleString()} tokens · ` +
      `~${costEur < 0.01 ? (costEur * 100).toFixed(3) + '¢' : costEur.toFixed(3) + '€'} · ` +
      `session: ~${adocTotalCost < 0.01 ? (adocTotalCost * 100).toFixed(2) + '¢' : adocTotalCost.toFixed(3) + '€'}` +
      `</span>`;
    msgEl.appendChild(footer);
    // Stocker le modèle utilisé pour le calcul suivant
    window._adocCurrentModel = null;
  }

  // ── P1-3 : Accumulateur contexte session ───────────────────────────────────
  // Après chaque groupe de 4 échanges, Haiku distille les entités clés
  // et les ajoute à adocSessionContext (injecté dans chaque system prompt)
  async function adocAccumulateSessionContext(plan, lastReply) {
    const workerUrl = adocGetWorkerUrl();
    if (!workerUrl) return;

    // Extraire les 8 derniers échanges pour Haiku
    const recent = adocConversations.slice(-8).map(m =>
      (m.role === 'user' ? 'Clinicien : ' : 'CC : ') + m.content.substring(0, 250)
    ).join('\n');

    const prompt = `Tu es un assistant clinique. Extrait les éléments clés de cette conversation thérapeutique en JSON strict.
Réponds UNIQUEMENT avec ce JSON, sans aucun texte avant ou après :
{
  "approche_active": "approche thérapeutique principale détectée ou null",
  "schemas_detectes": ["schema1", "schema2"],
  "style_attachement": "style ou null",
  "hypothese_courante": "hypothèse clinique principale en 1 phrase ou null",
  "axes_travail": ["axe1", "axe2"],
  "mots_cles": ["mot1", "mot2", "mot3"]
}

Conversation :
${recent}`;

    try {
      const r = await fetch(workerUrl, {
        method: 'POST', headers: { 'Content-Type': 'application/json', 'X-API-Key': adocGetApiKey() },
        body: JSON.stringify({ payload: {
          model: 'claude-haiku-4-5-20251001', max_tokens: 300,
          messages: [{ role: 'user', content: prompt }]
        }})
      });
      const data = await r.json();
      const raw  = data.content?.[0]?.text || '';
      const clean = raw.replace(/```json|```/g, '').trim();
      const ctx   = JSON.parse(clean);

      // Construire le contexte accumulé
      const parts = [];
      if (ctx.approche_active)    parts.push(`Approche : ${ctx.approche_active}`);
      if (ctx.schemas_detectes?.length)  parts.push(`Schémas : ${ctx.schemas_detectes.join(', ')}`);
      if (ctx.style_attachement)  parts.push(`Attachement : ${ctx.style_attachement}`);
      if (ctx.hypothese_courante) parts.push(`Hypothèse : ${ctx.hypothese_courante}`);
      if (ctx.axes_travail?.length)      parts.push(`Axes : ${ctx.axes_travail.join(', ')}`);

      if (parts.length) {
        adocSessionContext = parts.join(' · ');
        // Mettre à jour le champ UI contexte si visible
        const inp = document.getElementById('adoc-context-inp');
        if (inp && !inp.value) inp.value = adocSessionContext;
        console.log('[P1-3 SessionCtx]', adocSessionContext);
      }
    } catch(e) {
      console.warn('[P1-3] accumulateur contexte:', e.message);
    }
  }

  // ── P3-2 : Sync-check D1 ↔ Vectorize ────────────────────────────────────────
  // P3-1 : Panel de référence bibliographique au clic sur [REF:n]
  window.adocShowRefPanel = function(n, refMapStr) {
    let map = {};
    try { map = typeof refMapStr === 'object' ? refMapStr : JSON.parse(refMapStr.replace(/'/g, '"')); } catch {}
    const ref = map[n] || adocLastRefMap[n];
    if (!ref) return;
    // Enlever ancien panel
    const old = document.getElementById('adoc-ref-panel');
    if (old) old.remove();
    const panel = document.createElement('div');
    panel.id = 'adoc-ref-panel';
    panel.style.cssText = 'position:fixed;bottom:80px;right:20px;background:#fff;border:1px solid var(--stone-300);border-radius:10px;padding:14px 18px;max-width:340px;box-shadow:0 4px 20px rgba(0,0,0,.15);z-index:9999;font-size:12px;line-height:1.5';
    panel.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:8px">
        <span style="font-weight:700;color:var(--terracotta-700)">${adocIconSvg('icon-library')} Référence [${n}]</span>
        <button type="button" onclick="this.closest('#adoc-ref-panel').remove()" aria-label="Fermer la référence" style="background:none;border:none;cursor:pointer;color:#999;font-size:16px;margin-left:12px;font-family:inherit;">${adocIconSvg('icon-close')}</button>
      </div>
      <div style="color:var(--ink);font-weight:600">${ref.book_title}</div>
      ${ref.author ? `<div style="color:var(--muted)">${ref.author}</div>` : ''}
      ${ref.page_number ? `<div style="color:var(--petrol-800)">Page ${ref.page_number}</div>` : ''}
      ${ref.approach ? `<div style="margin-top:4px;background:var(--ivory);padding:2px 8px;border-radius:20px;display:inline-block;font-size:10px;color:var(--terracotta-700)">${ref.approach}</div>` : ''}
    `;
    document.body.appendChild(panel);
    // Auto-fermeture 6s
    setTimeout(() => panel.remove(), 6000);
  };

  window.adocRunSyncCheck = async function() {
    const btn = document.getElementById('adoc-sync-btn');
    const res = document.getElementById('adoc-sync-result');
    if (!btn || !res) return;

    btn.disabled    = true;
    btn.innerHTML   = adocIconSvg('icon-progress') + ' Vérification…';
    res.style.display = 'none';

    try {
      const workerUrl = adocGetWorkerUrl();
      const resp = await fetch(workerUrl + '/sync-check', { method: 'GET' });
      const data = await resp.json();

      if (data.error) {
        res.innerHTML = `${adocIconSvg('icon-error')} ${adocEsc(data.error)}`;
        res.style.display = 'block';
        return;
      }

      const icon    = data.all_synced ? adocIconSvg('icon-verify') : (data.missing_approaches?.length ? adocIconSvg('icon-error') : adocIconSvg('icon-warning'));
      const status  = data.all_synced ? 'Synchronisé' : 'Désynchronisé';
      const missing = data.missing_approaches?.length
        ? `<br>${adocIconSvg('icon-error')} Manquants : ${data.missing_approaches.join(', ')}`
        : '';
      const partial = data.partial_approaches?.length
        ? `<br>${adocIconSvg('icon-warning')} Partiels : ${data.partial_approaches.join(', ')}`
        : '';

      // Tableau des résultats par approche
      const rows = (data.details || []).map(d =>
        `<tr>
          <td style="padding:1px 4px">${d.approach}</td>
          <td style="padding:1px 4px;text-align:right">${d.d1_chunks.toLocaleString('fr')}</td>
          <td style="padding:1px 4px;text-align:center">${d.status === 'ok' ? adocIconSvg('icon-verify') : d.status === 'missing' ? adocIconSvg('icon-error') : adocIconSvg('icon-warning')} ${d.sync_rate}%</td>
        </tr>`
      ).join('');

      res.innerHTML =
        `<strong>${icon} ${status}</strong> · D1: ${(data.d1_total||0).toLocaleString('fr')} chunks${missing}${partial}` +
        (rows ? `<br><table style="width:100%;margin-top:4px;font-size:9px;border-collapse:collapse">
          <tr style="color:var(--terracotta-700);font-weight:600"><td>Approche</td><td style="text-align:right">D1</td><td style="text-align:center">Sync</td></tr>
          ${rows}
        </table>` : '');
      res.style.display = 'block';

    } catch(e) {
      res.innerHTML = `${adocIconSvg('icon-error')} Erreur : ${adocEsc(e.message)}`;
      res.style.display = 'block';
    } finally {
      btn.disabled    = false;
      btn.innerHTML   = adocIconSvg('icon-search') + ' Vérifier sync D1↔Vector';
    }
  };

  // UX-10A Étape 1 — jauge d'usage D1/R2 (lecture seule, mode développeur). Affiche les
  // chiffres bruts renvoyés par /storage-stats tels quels, sans interprétation ni alerte —
  // Christophe reste seul décisionnaire de quand une suppression manuelle vaut la peine.
  window.adocRunStorageStats = async function() {
    const btn = document.getElementById('adoc-storage-btn');
    const res = document.getElementById('adoc-storage-result');
    if (!btn || !res) return;

    btn.disabled = true;
    btn.innerHTML = adocIconSvg('icon-progress') + ' Lecture…';
    res.style.display = 'none';

    try {
      const workerUrl = adocGetWorkerUrl();
      const resp = await fetch(workerUrl + '/storage-stats', { headers: { 'X-API-Key': adocGetApiKey() } });
      const data = await resp.json();
      if (data.error) {
        res.innerHTML = `${adocIconSvg('icon-error')} ${adocEsc(data.error)}`;
        res.style.display = 'block';
        return;
      }

      const d1 = data.d1 || {};
      const tableRows = Object.entries(d1.tables || {}).map(([name, t]) =>
        `<tr><td style="padding:1px 4px">${adocEsc(name)}</td><td style="padding:1px 4px;text-align:right">${t.rowCount != null ? t.rowCount.toLocaleString('fr') : '—'}</td></tr>`
      ).join('');
      const dbSizeLine = d1.databaseSizeAvailable
        ? `Taille base : ${d1.databaseSizeMb.toLocaleString('fr')} Mo`
        : `Taille base : non mesurable depuis ce binding`;

      const r2 = data.r2 || {};
      const r2Line = r2.available
        ? `R2 (${adocEsc(r2.bucket)}) : ${r2.objectCount.toLocaleString('fr')} objet(s) · ${r2.totalSizeMb.toLocaleString('fr')} Mo`
        : `R2 : indisponible (${adocEsc(r2.note || 'non configuré')})`;

      res.innerHTML =
        `<table style="width:100%;font-size:9px;border-collapse:collapse">
          <tr style="color:var(--terracotta-700);font-weight:600"><td>Table D1</td><td style="text-align:right">Lignes</td></tr>
          ${tableRows}
        </table>
        <div style="margin-top:4px">${adocEsc(dbSizeLine)}</div>
        <div style="margin-top:2px">${r2Line}</div>`;
      res.style.display = 'block';
    } catch (e) {
      res.innerHTML = `${adocIconSvg('icon-error')} Erreur : ${adocEsc(e.message)}`;
      res.style.display = 'block';
    } finally {
      btn.disabled = false;
      btn.innerHTML = adocIconSvg('icon-cloud') + ' Jauge d’usage D1/R2';
    }
  };

  window.adocKvClear = function() {
    adocKvPatientId = null;
    adocKvHistory   = [];
    document.getElementById('adoc-kv-patient-id').value = '';
    document.getElementById('adoc-kv-status').textContent = '';
    document.getElementById('adoc-kv-history').style.display = 'none';
  };

  // ── M3 : adocLongDoc — Génération par chapitres avec continuation M2 ──
  // Triggered pour intent=cours|document avec max_tokens >= 4000
  // 1) Haiku génère un plan de chapitres JSON (4-8 chapitres)
  // 2) Chaque chapitre streamé séquentiellement avec Sonnet, cible 800-1500 mots
  //    (rend la continuation exceptionnelle plutôt que fréquente)
  // 3) Une continuation automatique max par chapitre ; au-delà, PAUSE explicite
  //    avec 4 choix (Phase B0 — avant : jusqu'à 5 continuations automatiques,
  //    et le badge "Document complet" s'affichait même sur un chapitre resté
  //    tronqué. Désormais : jamais de coche ni de "complet" sur un chapitre ou
  //    un document qui n'a pas fini normalement).
  // 4) Assemblage final → adocHandleReply
  //
  // État conservé par génération (chapterIndex, chapters, currentChapterText,
  // completedDocument, stopReason, plan, sources, etc.) dans un objet dédié par
  // docId — jamais une variable globale partagée entre deux documents longs.
  window._adocLongDocState = window._adocLongDocState || {};

  function adocLongDocRenderChoice(docId, chapTitre) {
    const state = window._adocLongDocState[docId];
    if (!state || !state.msgEl) return;
    adocLongDocRemoveChoice(docId);
    const box = document.createElement('div');
    box.className = 'cc-continue-prompt';
    box.id = 'cc-longdoc-choice-' + docId;
    box.setAttribute('role', 'group');
    box.setAttribute('aria-label', 'Chapitre interrompu — un choix est nécessaire');
    box.innerHTML =
      '<div class="cc-continue-text">Le chapitre « ' + adocEsc(chapTitre) + ' » est plus long que prévu ' +
      'et reste incomplet après une suite automatique. Que veux-tu faire ?</div>' +
      '<div class="cc-continue-actions">' +
        '<button type="button" class="cc-continue-btn" onclick="window.adocLongDocChoice(\'' + docId + '\',\'continue\')">Continuer ce chapitre</button>' +
        '<button type="button" class="cc-continue-stop-btn" onclick="window.adocLongDocChoice(\'' + docId + '\',\'keep\')">Conserver ce chapitre incomplet</button>' +
        '<button type="button" class="cc-continue-stop-btn" onclick="window.adocLongDocChoice(\'' + docId + '\',\'skip\')">Passer au chapitre suivant</button>' +
        '<button type="button" class="cc-continue-stop-btn" onclick="window.adocLongDocChoice(\'' + docId + '\',\'stop\')">Arrêter et produire le document actuel</button>' +
      '</div>';
    state.msgEl.appendChild(box);
    const area = document.getElementById('adoc-messages');
    if (area) area.scrollTop = area.scrollHeight;
  }
  function adocLongDocRemoveChoice(docId) {
    const el = document.getElementById('cc-longdoc-choice-' + docId);
    if (el) el.remove();
  }

  // Un seul point d'entrée pour les 4 boutons — resumeResolve est nullé dès
  // consommation, donc un double-clic (synchrone, JS mono-thread) ne peut pas
  // déclencher deux résolutions de la même pause.
  window.adocLongDocChoice = function (docId, action) {
    const state = window._adocLongDocState[docId];
    if (!state || !state.resumeResolve) return;
    adocLongDocRemoveChoice(docId);
    const resolve = state.resumeResolve;
    state.resumeResolve = null;
    resolve(action);
  };

  async function adocLongDocStreamChapter(docId, msgs) {
    const state = window._adocLongDocState[docId];
    const r = await fetch(state.workerUrl, {
      method: 'POST', headers: { 'Content-Type': 'application/json', 'X-API-Key': adocGetApiKey() },
      body: JSON.stringify({ payload: {
        model: state.MODEL, max_tokens: 4000, stream: true,
        system: state.systemPrompt, messages: msgs,
        tools: [{ type: 'web_search_20250305', name: 'web_search' }],
        tool_choice: { type: 'auto' }
      }})
    });
    if (!r.ok) return;
    const rdr = r.body.getReader();
    const decoder = new TextDecoder();
    let buf = '';
    while (true) {
      const { done, value } = await rdr.read();
      if (done) break;
      buf += decoder.decode(value, { stream: true });
      const ls = buf.split('\n'); buf = ls.pop();
      for (const l of ls) {
        if (!l.startsWith('data: ')) continue;
        const dat = l.slice(6).trim();
        if (dat === '[DONE]') continue;
        try {
          const ev = JSON.parse(dat);
          if (ev.type === 'content_block_delta' && ev.delta && ev.delta.type === 'text_delta') {
            state.currentChapterText += ev.delta.text;
            adocUpdateStreamMsg(state.streamMsgId, state.completedDocument + '\n\n' + state.currentChapterText);
          }
          if (ev.type === 'message_delta' && ev.delta && ev.delta.stop_reason) state.stopReason = ev.delta.stop_reason;
        } catch(ex) {}
      }
    }
  }

  async function adocLongDocGenerateChapter(docId) {
    const state = window._adocLongDocState[docId];
    const chap = state.chapters[state.chapterIndex];
    const chapBadge = document.createElement('div');
    chapBadge.style.cssText = 'font-size:11px;color:var(--petrol-800);padding:2px 10px;font-weight:600;margin:2px 0;';
    chapBadge.innerHTML = adocIconSvg('icon-writing') + ' ' + adocEsc(chap.titre) + '…';
    if (state.msgEl) state.msgEl.appendChild(chapBadge);

    const chapUserMsg = chap.titre + '\n\nInstructions : ' + chap.instructions
      + (state.completedDocument.length > 100 ? '\n\nContexte déjà rédigé (fin) :\n' + state.completedDocument.substring(state.completedDocument.length - 1200) : '')
      + '\n\nLongueur cible : 800 à 1500 mots pour ce chapitre — reste dans cette fourchette sauf si le sujet exige réellement plus.';
    // FIX-LONGDOC-MSGS : fusion en un seul message user (2 user consécutifs = erreur API silencieuse)
    const chapUserFull = state.text + '\n\n---\n\n' + chapUserMsg;
    const chapMsgs = [{ role: 'user', content: chapUserFull }];

    state.currentChapterText = '';
    state.stopReason = null;
    await adocLongDocStreamChapter(docId, chapMsgs);

    // (b) une continuation automatique maximum
    if (state.stopReason === 'max_tokens') {
      const badge = document.createElement('span');
      badge.style.cssText = 'font-size:10px;color:var(--petrol-800);background:rgba(31,80,83,0.15);border:1px solid rgba(31,80,83,0.3);border-radius:10px;padding:1px 8px;margin:2px;';
      badge.textContent = '▶ suite ch.' + (state.chapterIndex + 1) + '.1';
      if (state.msgEl) state.msgEl.appendChild(badge);
      state.stopReason = null;
      await adocLongDocStreamChapter(docId, [...chapMsgs,
        { role: 'assistant', content: state.currentChapterText },
        { role: 'user', content: 'Continue exactement là où tu t\'en étais arrêté.' }
      ]);
    }

    // (c)/(d) encore interrompu après la suite automatique → pause, jamais de
    // nouvelle suite sans validation, jamais de coche tant que ça dure.
    let manualRound = 1;
    while (state.stopReason === 'max_tokens') {
      adocLongDocRenderChoice(docId, chap.titre);
      const action = await new Promise(resolve => { state.resumeResolve = resolve; });

      if (action === 'continue') {
        manualRound++;
        const badge = document.createElement('span');
        badge.style.cssText = 'font-size:10px;color:var(--petrol-800);background:rgba(31,80,83,0.15);border:1px solid rgba(31,80,83,0.3);border-radius:10px;padding:1px 8px;margin:2px;';
        badge.textContent = '▶ suite ch.' + (state.chapterIndex + 1) + '.' + manualRound;
        if (state.msgEl) state.msgEl.appendChild(badge);
        state.stopReason = null;
        await adocLongDocStreamChapter(docId, [...chapMsgs,
          { role: 'assistant', content: state.currentChapterText },
          { role: 'user', content: 'Continue exactement là où tu t\'en étais arrêté.' }
        ]);
        continue; // reboucle : re-teste stopReason
      }
      if (action === 'keep') {
        chapBadge.innerHTML = adocIconSvg('icon-warning') + ' ' + adocEsc(chap.titre) + ' (conservé incomplet)';
        state.hadIncompleteChapter = true;
        state.completedDocument += '\n\n' + state.currentChapterText;
        return;
      }
      if (action === 'skip') {
        chapBadge.innerHTML = adocIconSvg('icon-skip') + ' ' + adocEsc(chap.titre) + ' (chapitre ignoré, resté incomplet)';
        state.hadIncompleteChapter = true;
        state.completedDocument += '\n\n[Ce chapitre a été ignoré à la demande de la thérapeute — resté incomplet après plusieurs tentatives.]';
        return;
      }
      // action === 'stop'
      chapBadge.innerHTML = adocIconSvg('icon-stop') + ' ' + adocEsc(chap.titre) + ' (arrêté ici)';
      state.hadIncompleteChapter = true;
      state.stoppedEarly = true;
      return;
    }

    // Chapitre terminé normalement — seul cas qui reçoit la coche
    chapBadge.innerHTML = adocIconSvg('icon-verify') + ' ' + adocEsc(chap.titre);
    state.completedDocument += '\n\n' + state.currentChapterText;
  }

  // ── LOT 30 — chemin dédié pour une demande "images seules, sans texte" ──
  // Séparé du moteur de document long : aucun planificateur de chapitres, aucune instruction
  // de longueur de mots, aucun plancher de tokens hérité. Un seul appel léger propose des
  // requêtes d'image + textes alternatifs, assemblés directement en HTML autonome ici même
  // (jamais généré paragraphe par paragraphe par le modèle). La résolution réelle des images
  // (<img data-pexels="...">) est laissée à adocResolveImages, appelé par adocHandleReply
  // (via adocFinalizeGeneration) exactement comme pour tout autre document HTML — mécanisme
  // déjà existant et éprouvé, jamais dupliqué ici.
  window.adocVisualOnlyDoc = async function(text, plan, workerUrl) {
    // Nombre d'images cohérent avec la demande si un nombre est précisé ("4 pages", "6 images"…),
    // sinon une valeur par défaut raisonnable.
    const _countMatch = text.match(/\b(\d{1,2})\s*(page|pages|image|images|photo|photos|diapo|diapos|diapositive|diapositives)\b/i);
    const targetCount = _countMatch ? Math.min(Math.max(parseInt(_countMatch[1], 10), 1), 12) : 6;

    let title = plan?.topic_summary || 'Planche visuelle';
    let images = [];
    try {
      const prompt = 'Sujet clinique : "' + (plan?.topic_summary || text.slice(0, 200)) + '".\n'
        + 'Propose exactement ' + targetCount + ' requêtes de recherche d’image (banque Pexels, en '
        + 'anglais, concrètes et variées — jamais deux fois la même) illustrant ce sujet, chacune avec '
        + 'un texte alternatif court en français (une phrase, jamais vide) décrivant ce que l’image '
        + 'doit montrer.\n'
        + 'Réponds UNIQUEMENT avec ce JSON, sans texte avant ni après :\n'
        + '{"title":"titre court en français","images":[{"query":"...","alt":"..."}]}';
      const r = await fetch(workerUrl, {
        method: 'POST', headers: { 'Content-Type': 'application/json', 'X-API-Key': adocGetApiKey() },
        body: JSON.stringify({ payload: {
          model: 'claude-haiku-4-5-20251001', max_tokens: 700,
          messages: [{ role: 'user', content: prompt }]
        }})
      });
      const d = await r.json();
      const t = d.content?.[0]?.text || '{}';
      const m = t.match(/\{[\s\S]*\}/);
      const parsed = JSON.parse(m ? m[0] : '{}');
      if (parsed.title) title = parsed.title;
      if (Array.isArray(parsed.images)) {
        images = parsed.images.filter(im => im && im.query).slice(0, targetCount);
      }
    } catch (e) {
      console.warn('[LOT30] adocVisualOnlyDoc — planification des images en échec, repli générique:', e && e.message);
    }

    // Repli — jamais un document sans aucune image, même si l'appel ci-dessus échoue
    // totalement (réseau, JSON malformé) : mêmes principes que les replis _fallback/
    // FIX-EMPTY-PLAN déjà établis ailleurs dans ce fichier.
    if (!images.length) {
      const base = (plan?.topic_summary || text).replace(/[^a-z0-9À-ɏ\s]/gi, '').trim().slice(0, 60) || 'therapie';
      images = Array.from({ length: targetCount }, (_, i) => ({
        query: base, alt: 'Illustration ' + (i + 1) + ' — ' + base,
      }));
    }

    const figuresHtml = images.map((im) =>
      '<figure style="margin:0 0 24px;">'
      + '<img data-pexels="' + adocEsc(im.query) + '" alt="' + adocEsc(im.alt) + '" style="width:100%;border-radius:10px;object-fit:cover;display:block;">'
      + '<figcaption style="margin-top:8px;font-size:13px;color:var(--muted);">' + adocEsc(im.alt) + '</figcaption>'
      + '</figure>'
    ).join('\n');

    // Charte C Concept&Dev en dur, identique à celle imposée à tout document HTML autonome
    // ailleurs dans ce fichier (cf. adocBuildSystemPrompt/_execContext) — le fichier vit seul.
    return '<!DOCTYPE html><html><head><meta charset="utf-8"><title>' + adocEsc(title) + '</title>'
      + '<style>:root{--mer:#1f5053;--deep:#102f31;--vert-sauge:#c9c3b8;--beige:#ddd7cc;--sable:#f6f2ea;--surf:#f6f2ea;--text:#273331;--muted:#5d6966;--blanc:#FFFFFF}'
      + 'body{margin:0;padding:32px;background:var(--sable);color:var(--text);font-family:"IBM Plex Sans",Arial,sans-serif;}'
      + 'h1{font-family:"Source Serif 4",Georgia,serif;color:var(--deep);margin:0 0 24px;}</style></head>'
      + '<body><h1>' + adocEsc(title) + '</h1>' + figuresHtml + '</body></html>';
  };

  window.adocLongDoc = async function(text, plan, ragResult, systemPrompt, streamMsgId, workerUrl) {
    const docId = streamMsgId; // un seul long-doc actif par message assistant — déjà unique
    const msgEl = document.getElementById(streamMsgId);

    // ── Plan de chapitres via Haiku ──
    // Item 60 construction — calibration de l'intervalle de chapitres sur la durée demandée
    // (plan.duree_minutes, Option A : extraite par le planificateur lui-même, jamais une regex
    // locale — cf. investigation item 60). Règle simple, documentée : ~1 chapitre par 10 à 15
    // minutes de contenu oral estimé, plancher 2, plafond 10. Sans durée connue (null, valeur la
    // plus fréquente aujourd'hui), comportement STRICTEMENT inchangé ("4 à 8", intervalle fixe
    // historique) — jamais de calibration inventée à partir d'une absence d'information.
    let chapterRangeInstruction = 'Génère 4 à 8 chapitres.';
    if (typeof plan?.duree_minutes === 'number' && plan.duree_minutes > 0) {
      const minChapters = Math.min(10, Math.max(2, Math.floor(plan.duree_minutes / 15)));
      const maxChapters = Math.min(10, Math.max(minChapters, Math.ceil(plan.duree_minutes / 10)));
      chapterRangeInstruction = 'Durée cible : ' + plan.duree_minutes + ' minutes.\n'
        + 'Génère ' + (minChapters === maxChapters ? minChapters + ' chapitres' : minChapters + ' à ' + maxChapters + ' chapitres') + ' (calibré sur la durée cible ci-dessus).';
    } else {
      chapterRangeInstruction = 'Durée cible : non précisée.\nGénère 4 à 8 chapitres.';
    }
    let chapters = [];
    try {
      const chapPrompt = 'Planifie un document long sur : "' + plan.topic_summary + '".\n'
        + 'Intent : ' + plan.intent + '. Audience : ' + (plan.audience_type || 'praticien') + '.\n'
        + chapterRangeInstruction + ' Réponds UNIQUEMENT avec :\n'
        + '[{"titre":"Chapitre 1 : ...","instructions":"contenu attendu en 2-3 phrases"},...]';
      const cr = await fetch(workerUrl, {
        method: 'POST', headers: { 'Content-Type': 'application/json', 'X-API-Key': adocGetApiKey() },
        body: JSON.stringify({ payload: {
          model: 'claude-haiku-4-5-20251001', max_tokens: 800,
          messages: [{ role: 'user', content: chapPrompt }]
        }})
      });
      const cd = await cr.json();
      const ct = cd.content?.[0]?.text || '[]';
      const cm = ct.match(/\[[\s\S]*\]/);
      chapters = JSON.parse(cm ? cm[0] : '[]');
    } catch(e) { chapters = []; }

    if (!Array.isArray(chapters) || !chapters.length) {
      chapters = [
        { titre: 'Introduction et fondements théoriques', instructions: 'Contexte, définitions, enjeux cliniques.' },
        { titre: 'Modèles et approches', instructions: 'Théories principales, auteurs clés, comparaisons.' },
        { titre: 'Applications et techniques cliniques', instructions: 'Protocoles, outils, cas pratiques.' },
        { titre: 'Synthèse et perspectives', instructions: 'Conclusion, limites, orientations futures.' }
      ];
    }

    const planBadge = document.createElement('div');
    planBadge.style.cssText = 'font-size:11px;color:var(--muted);padding:4px 10px;font-style:italic;border-left:2px solid var(--petrol-800);margin:4px 0;display:flex;align-items:center;gap:0.35rem;';
    // Harmonisation Kit v2.4, Volet 2 — remplace l'émoji brut 📋 (\u{1F4CB}, invisible à un
    // audit texte car encodé en séquence d'échappement JS) par l'icône du sprite interne
    // existant (icon-documents), texte explicite conservé à côté.
    planBadge.innerHTML = '<svg class="sc-icon" aria-hidden="true" focusable="false"><use href="#icon-documents"></use></svg> Document ' + chapters.length + ' chapitres — génération en cours…';
    if (msgEl) msgEl.appendChild(planBadge);

    window._adocLongDocState[docId] = {
      chapterIndex: 0, chapters, currentChapterText: '', completedDocument: '',
      stopReason: null, plan, sources: ragResult, systemPrompt, workerUrl, text,
      streamMsgId, msgEl, MODEL: 'claude-sonnet-4-6', resumeResolve: null,
      hadIncompleteChapter: false, stoppedEarly: false
    };
    const state = window._adocLongDocState[docId];

    for (state.chapterIndex = 0; state.chapterIndex < chapters.length; state.chapterIndex++) {
      await adocLongDocGenerateChapter(docId);
      if (state.stoppedEarly) break;
    }

    const isComplete = !state.hadIncompleteChapter;
    planBadge.innerHTML = isComplete
      ? adocIconSvg('icon-verify') + ' Document complet — ' + chapters.length + ' chapitres'
      : adocIconSvg('icon-warning') + ' Document généré avec au moins un chapitre incomplet ou ignoré — jamais qualifié de complet';

    let finalText = state.completedDocument.trim();
    if (!finalText && state.stoppedEarly) {
      // Arrêt demandé avant la fin du tout premier chapitre — jamais retourner une
      // chaîne vide : ça déclencherait silencieusement le repli vers la génération
      // standard côté appelant, à l'opposé du choix explicite de la thérapeute.
      finalText = 'Document interrompu à la demande de la thérapeute avant la fin du premier chapitre — aucun contenu complet à afficher pour l\'instant.';
    }
    // FIX-EMOJI-LEGACY : même filtre que le chemin HTML-first (cf. adocHandleReply) — les
    // documents longs (cours/document, potentiellement Liens transversaux selon l'intent
    // détecté par le planner) partagent ce risque d'emojis décoratifs jamais filtrés.
    finalText = adocStripEmoji(finalText);
    // FIX-LONGDOC-REF : résoudre les [REF:n] en citations cliquables avant rendu final
    const fullDocRendered = (typeof adocRenderCiteInline === 'function')
      ? adocRenderCiteInline(finalText, adocLastRefMap)
      : finalText;
    adocUpdateStreamMsg(streamMsgId, fullDocRendered);
    delete window._adocLongDocState[docId];
    return fullDocRendered;
  };

  // ═══ INTÉGRATION ÉCRAN D'ACCUEIL #cc-landing (Kit v2.4 — Volet 1) ═══
  // Le nouvel écran d'accueil (#cc-landing, cf. début de <body>) remplace l'ancien état
  // "welcome" affiché au chargement. Il gère sa propre UI via son script embarqué et se
  // contente de dispatcher 'conseiller-clinique:start' ({prompt, format}) quand le
  // thérapeute valide sa question — c'est le point d'intégration prévu par ce fichier.
  // detail.format porte désormais documentKind (fiche|carrousel|tableau|script|liens|null),
  // JAMAIS une clé d'un ancien "formatPhrases" concaténé au texte : cette concaténation est
  // supprimée (MISSION-HARMONISATION-CORRIGEE.md, Volet 1, point 3 — "cette concaténation
  // est supprimée"). Le texte tapé part à l'identique dans #adoc-input et vers adocSend/
  // adocMultiPlan (réutilisé tel quel, jamais dupliqué) ; documentKind voyage séparément via
  // window.adocPendingDocumentKind, consommé une seule fois par adocSend (cf. plus bas dans
  // cette IIFE, bloc de clarification), qui l'attache à plan.documentKind — une contrainte
  // structurelle additive, jamais un mot ajouté au prompt.
  window.addEventListener('conseiller-clinique:start', function (evt) {
    const detail = evt.detail || {};
    const prompt = (detail.prompt || '').trim();
    const documentKind = detail.format || null;
    if (!prompt) return;

    // UX-8B Lot 2 — charte choisie pour CETTE demande précise (jamais un réglage global figé).
    // '' ou absente ⇒ adocResolveBrandKitForGeneration retombe sur la charte par défaut.
    adocActiveBrandKitId = detail.brandKitId || '';
    // Parité 0F (monobloc) — capturé UNE FOIS par requête, même patron que adocActiveBrandKitId
    // ci-dessus : jamais lu par le moteur structuré (adocResolveBrandKitForGeneration), qui
    // continue d'utiliser adocActiveBrandKitId seul, comportement strictement inchangé.
    adocActiveBrandKitExplicit = !!detail.explicitBrandKit;

    const landing = document.getElementById('cc-landing');
    if (landing) landing.style.display = 'none';

    if (typeof openAssistDoc === 'function') openAssistDoc();

    window.adocPendingDocumentKind = documentKind;
    const input = document.getElementById('adoc-input');
    if (input) {
      input.value = prompt;
      if (typeof adocResize === 'function') adocResize(input);
    }
    if (typeof adocSend === 'function') adocSend();
  });

  // ═══ Chiffres réels de la bibliothèque pour #cc-landing (au chargement) ═══
  // Un seul appel /library-stats pour tout l'écran désormais — cf. adocLoadLibraryStats()
  // plus haut dans cette IIFE, qui alimente aussi le point d'intégration
  // window.setConseillerCliniqueLibraryStats() prévu par l'accueil.
  adocLoadLibraryStats();

  // ═══ UX-8B Lot 2 — liste réelle des chartes graphiques pour #cc-landing (au chargement) ═══
  // Même patron que ci-dessus : un vrai GET /brand-kits, jamais une liste codée en dur, qui
  // alimente le point d'intégration window.setConseillerCliniqueBrandKits() prévu par l'accueil.
  adocFetchBrandKits();

  // ═══════════════════════════════════════════════════════════════════════
  // Phase UX-1 / UX-1ter — Popup document en taille réelle (aperçu avant
  // téléchargement) + lightbox image dans les documents générés
  // ═══════════════════════════════════════════════════════════════════════
  // Remplace les anciens mécanismes "window.open(url, '_blank')" /
  // "w.document.write(art.html)" par une vraie popup in-page, scrollable,
  // accessible au clavier (focus au close, Échap ferme, Tab piégé entre le
  // bouton fermer et l'iframe). N'importe quel artefact (html, pdf, docx,
  // xlsx, pptx, zip) peut s'y ouvrir — on utilise dans l'ordre de préférence
  // le HTML source brut, puis l'aperçu HTML converti en blob, puis l'URL de
  // prévisualisation Worker (fonctionne aussi pour un PDF, rendu nativement
  // par le navigateur dans l'iframe).
  let adocDocPopupLastFocus = null;

  function adocDocPopupKeydown(e) {
    if (e.key === 'Escape') { e.preventDefault(); adocCloseDocPopup(); return; }
    if (e.key !== 'Tab') return;
    const closeBtn = document.getElementById('cc-doc-popup-close');
    const iframe = document.querySelector('#cc-doc-popup-body iframe');
    const focusable = [closeBtn, iframe].filter(Boolean);
    if (focusable.length < 2) return;
    const first = focusable[0], last = focusable[focusable.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  }

  function adocOpenDocPopupWithSrc(title, src, isSrcDoc) {
    const overlay = document.getElementById('cc-doc-popup-overlay');
    const body = document.getElementById('cc-doc-popup-body');
    const titleEl = document.getElementById('cc-doc-popup-title');
    if (!overlay || !body || !src) return;
    titleEl.textContent = title || 'Aperçu du document';
    body.innerHTML = '';
    const iframe = document.createElement('iframe');
    iframe.setAttribute('sandbox', 'allow-scripts');
    iframe.setAttribute('title', title || 'Aperçu du document');
    // Un clic dans le document (p.ex. sur une image pour l'agrandir) déplace le focus
    // clavier DANS l'iframe : Échap n'y remonterait plus jamais jusqu'à notre écouteur
    // sur `document` (les évènements clavier ne traversent pas la frontière d'iframe).
    // Relais direct quand l'origine le permet (srcdoc/blob — le cas courant ici) ; pour
    // un aperçu vraiment cross-origin, le navigateur bloque cet accès de toute façon —
    // rien à faire de plus côté script, il suffit alors de recliquer hors de l'iframe.
    iframe.addEventListener('load', function () {
      try {
        iframe.contentDocument?.addEventListener('keydown', function (e) {
          if (e.key === 'Escape') window.adocCloseDocPopup();
        });
      } catch (_e) { /* iframe réellement cross-origin — inaccessible, attendu */ }
    });
    if (isSrcDoc) iframe.srcdoc = src; else iframe.src = src;
    body.appendChild(iframe);

    adocDocPopupLastFocus = document.activeElement;
    overlay.classList.add('active');
    document.getElementById('cc-doc-popup-close')?.focus();
    document.addEventListener('keydown', adocDocPopupKeydown);
  }

  window.adocCloseDocPopup = function () {
    const overlay = document.getElementById('cc-doc-popup-overlay');
    if (!overlay || !overlay.classList.contains('active')) return;
    overlay.classList.remove('active');
    const body = document.getElementById('cc-doc-popup-body');
    if (body) body.innerHTML = '';
    document.removeEventListener('keydown', adocDocPopupKeydown);
    if (adocDocPopupLastFocus && typeof adocDocPopupLastFocus.focus === 'function') {
      adocDocPopupLastFocus.focus();
    }
  };

  document.getElementById('cc-doc-popup-overlay')?.addEventListener('click', function (e) {
    if (e.target === this) window.adocCloseDocPopup();
  });

  // Point d'entrée unique : ouvre un artefact stocké dans window._adocArtifacts
  // à sa taille réelle de rendu, quel que soit son format.
  window.adocOpenDocPopup = function (storeKey) {
    const art = window._adocArtifacts?.[storeKey];
    if (!art) return;
    // UX-8W : une Fiche synthèse structurée s'ouvre désormais dans l'écran de travail dédié
    // (adocRenderClinicalDocument, sources, bibliothèque, export) plutôt que le popup iframe
    // générique — tous les autres formats gardent ce popup, inchangé.
    // Audit correctif, Partie B point 10 — test unique sur l'objet de capacités (plutôt qu'un
    // test _adocStructuredDoc ne reconnaissant que le moteur structuré) : un document de repli
    // legacy-html porte aussi capabilities.workspace=true (voir adocFinalizeGeneration) et doit
    // s'ouvrir dans le même écran de travail, qui adapte son affichage selon le moteur.
    if (art._adocCapabilities && art._adocCapabilities.workspace) { window.adocOpenWorkspace(storeKey); return; }
    const title = (art.name || 'Document').replace(/-\d+$/, '').replace(/-/g, ' ');
    if (art.html) { adocOpenDocPopupWithSrc(title, art.html, true); return; }
    if (art.htmlBlobUrl) { adocOpenDocPopupWithSrc(title, art.htmlBlobUrl, false); return; }
    if (art.preview) { adocOpenDocPopupWithSrc(title, art.preview, false); return; }
    if (art.url) { adocOpenDocPopupWithSrc(title, art.url, false); return; }
  };

  // ═══════════════════════════════════════════════════════════════════════
  // Phase UX-2bis — Clarification intelligente avant génération
  // ═══════════════════════════════════════════════════════════════════════
  // Principe : avant chaque génération (soumission de l'accueil OU question
  // suivante en conversation — les deux passent par window.adocSend, seul
  // point de passage commun), un jugement Haiku évalue si la demande est
  // assez claire. « ready » → génération immédiate, aucun changement perçu.
  // « needs_clarification » → une question ciblée, plafonnée à 2 tours ;
  // au 3ᵉ jugement encore ambigu, on génère quand même en insérant les
  // hypothèses retenues dans un bandeau visible du document produit.
  //
  // Ne touche à aucune logique de génération existante : window.adocSend
  // (ci-dessus, inchangée) est capturée puis enveloppée. La fonction
  // d'origine n'est appelée qu'une fois la clarté acquise, avec le texte
  // final dans #adoc-input — exactement comme un envoi normal aujourd'hui.

  const adocSendOriginal = window.adocSend;

  // Prompt système FIXE (aucune variable interpolée) — pleinement éligible
  // au cache prompt déjà en place côté Worker (cache_control sur `system`
  // quand c'est une chaîne, cf. handleAnthropicProxy). Le contenu variable
  // (demande, historique, échanges de clarification) va dans `messages`,
  // jamais dans `system`, pour ne pas invalider le cache à chaque appel.
  const ADOC_CLARITY_SYSTEM_PROMPT =
    "Tu es l'évaluateur de clarté d'un conseiller clinique qui produit des documents " +
    "thérapeutiques (fiche synthèse, tableau comparatif, script verbatim, carrousel, carte " +
    "de liens transversaux) à partir d'une bibliothèque de référence.\n\n" +
    "Ta mission : juge si la demande fournie contient assez d'information pour produire un " +
    "document clinique de qualité, utile et bien ciblé. Un document trop générique parce que " +
    "la demande était ambiguë est un échec ; poser une question de clarification pour une " +
    "demande déjà claire est aussi un échec — ne demande une précision que si elle changerait " +
    "réellement le contenu produit.\n\n" +
    "Raisonne ouvertement sur ce qui manquerait pour bien répondre : un public visé, un " +
    "contexte clinique précis, une portée (comparer quoi à quoi, à quel niveau de détail), ou " +
    "toute autre information dont l'absence rendrait le document produit médiocre ou mal " +
    "ciblé. N'invente aucune règle liée à un domaine clinique particulier ou à un mot-clé " +
    "précis — le raisonnement doit rester général et s'appliquer à n'importe quel sujet.\n\n" +
    "Si une clarification est encore nécessaire, pose UNE SEULE question, simple et concrète, " +
    "avec 2 à 4 suggestions de réponse rapide. Si la demande (complétée le cas échéant par les " +
    "échanges de clarification déjà faits) est suffisante, réponds \"ready\" sans poser de " +
    "question.\n\n" +
    "Si le message utilisateur précise qu'un TYPE DE DOCUMENT est déjà définitivement choisi " +
    "(section \"TYPE DE DOCUMENT DÉJÀ CHOISI\" ci-dessous, le cas échéant), ce choix est " +
    "irrévocable et ne doit JAMAIS faire l'objet d'une question ni d'une suggestion de ta " +
    "part — évalue uniquement les autres éléments (public visé, contexte clinique, portée) " +
    "qui pourraient encore manquer pour ce type précis.\n\n" +
    "Enregistre systématiquement ton jugement via l'outil evaluate_clarity.";

  // Schéma exact demandé par le CDC UX-2bis — tool avec strict:true, forcé via
  // tool_choice. Garantit un JSON valide sans extraction regex/```json (à la
  // différence du patron existant dans evaluateWebConsultNeed()).
  const ADOC_CLARITY_TOOL = {
    name: 'evaluate_clarity',
    description: 'Enregistre le jugement de clarté sur la demande clinique en cours.',
    strict: true,
    input_schema: {
      type: 'object',
      properties: {
        status: { type: 'string', enum: ['ready', 'needs_clarification'] },
        understood_so_far: { type: 'string', description: 'Résumé en une phrase de ce qui est compris de la demande.' },
        missing: { type: 'array', items: { type: 'string' }, description: 'Éléments manquants pour produire un bon document ; liste vide si status=ready.' },
        question: { type: 'string', description: 'Une seule question ciblée, formulée simplement ; chaîne vide si status=ready.' },
        quick_replies: { type: 'array', items: { type: 'string' }, description: '2 à 4 suggestions de réponse courtes ; liste vide si status=ready.' },
        assumptions_if_proceeding: { type: 'array', items: { type: 'string' }, description: "Hypothèses que le système retiendrait s'il devait produire maintenant sans autre précision." }
      },
      required: ['status', 'understood_so_far', 'missing', 'question', 'quick_replies', 'assumptions_if_proceeding'],
      additionalProperties: false
    }
  };

  async function adocEvaluateClarity(context) {
    const workerUrl = adocGetWorkerUrl();
    if (!workerUrl || workerUrl === 'undefined') return null;

    let userContent = 'DEMANDE DU THÉRAPEUTE :\n"' + context.originalMessage + '"';
    if (context.qaPairs && context.qaPairs.length) {
      const qaText = context.qaPairs
        .map(function (p) { return 'Question posée : ' + p.question + '\nRéponse du thérapeute : ' + p.answer; })
        .join('\n\n');
      userContent += '\n\nÉCHANGES DE CLARIFICATION DÉJÀ FAITS :\n' + qaText;
    }
    // Bug confirmé — un type de document cliqué explicitement sur l'écran d'accueil
    // (window.adocPendingDocumentKind, cf. adocClarityDocumentKind) doit être connu de
    // l'évaluateur : sans cette section, rien ne l'empêchait de redemander un type déjà résolu.
    // Réutilise le même vocabulaire déjà affiché ailleurs pour ce choix (ADOC_GENERATION_KIND_LABELS,
    // cf. adocUpdateGenerationTitle) — jamais un libellé inventé séparément. Absent/null : aucun
    // changement, l'évaluateur juge librement comme avant (point 3 de la demande).
    if (context.explicitDocumentKind) {
      const kindLabel = ADOC_GENERATION_KIND_LABELS[context.explicitDocumentKind] || context.explicitDocumentKind;
      userContent += '\n\nTYPE DE DOCUMENT DÉJÀ CHOISI (irrévocable, ne jamais questionner) : ' + kindLabel + '.';
    }

    const resp = await fetch(workerUrl.replace(/\/+$/, ''), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-API-Key': adocGetApiKey() },
      body: JSON.stringify({
        payload: {
          provider: 'anthropic',
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 500,
          temperature: 0,
          system: ADOC_CLARITY_SYSTEM_PROMPT,
          messages: [{ role: 'user', content: userContent }],
          tools: [ADOC_CLARITY_TOOL],
          tool_choice: { type: 'tool', name: 'evaluate_clarity' }
        }
      })
    });
    if (!resp.ok) throw new Error('HTTP ' + resp.status);
    const data = await resp.json();
    const toolUse = (data.content || []).find(function (b) { return b.type === 'tool_use' && b.name === 'evaluate_clarity'; });
    if (!toolUse || !toolUse.input) throw new Error('Réponse sans bloc tool_use structuré');
    return toolUse.input; // déjà un objet JS conforme au schéma — aucune extraction regex/```json
  }

  // ── État de la boucle de clarification (une demande à la fois) ──
  let adocClarityRound = 0;
  let adocClarityAwaitingAnswer = false;
  let adocClarityOriginalMessage = '';
  let adocClarityQAPairs = [];
  let adocClarityLastQuestion = '';
  let adocClarityCardEl = null;
  // Kit v2.4 (Volet 1) — documentKind choisi sur l'écran d'accueil (window.adocPendingDocumentKind,
  // cf. listener 'conseiller-clinique:start'), capturé UNE SEULE FOIS au début d'une nouvelle
  // demande (même cycle de vie que adocClarityOriginalMessage/adocClarityQAPairs ci-dessus, pour
  // survivre aux allers-retours de clarification) puis lu-et-effacé par adocSendOriginal, qui
  // l'attache à plan.documentKind. Jamais réappliqué à une demande ultérieure non liée.
  let adocClarityDocumentKind = null;
  let adocDefaultInputPlaceholder = null; // capturé au premier remplacement, pour pouvoir le restaurer
  // Correctif UX-2bis (terrain, v1.4.0) : l'instruction de bandeau "Hypothèses retenues"
  // ne doit jamais apparaître dans la bulle utilisateur ni dans l'historique de
  // conversation — seulement transmise au modèle pour LA génération qui suit
  // immédiatement le plafond de clarification. Lue et effacée une seule fois par
  // window.adocSend (la version d'origine, plus bas), jamais réutilisée après.
  let adocClarityBannerNote = null;

  // Retour de test réel (Christophe) : le champ libre existait déjà mais n'était signalé que
  // par une ligne de texte discrète, invisible face aux boutons de suggestion. Le bouton
  // "Autre, précisez…" ci-dessous ne répond pas à ta place — il donne juste le focus au champ
  // de saisie, avec un placeholder explicite pendant que la carte attend une réponse.
  window.adocClarityFocusInput = function () {
    const input = document.getElementById('adoc-input');
    if (input) input.focus();
  };

  function adocSetClarityPlaceholder() {
    const input = document.getElementById('adoc-input');
    if (!input) return;
    if (adocDefaultInputPlaceholder === null) adocDefaultInputPlaceholder = input.placeholder;
    input.placeholder = 'Aucune suggestion ne convient ? Précisez votre besoin ici…';
  }

  function adocRestoreDefaultPlaceholder() {
    const input = document.getElementById('adoc-input');
    if (input && adocDefaultInputPlaceholder !== null) input.placeholder = adocDefaultInputPlaceholder;
  }

  // Harmonisation A→D — illustrations décoratives (jamais l'unique indicateur ; le texte
  // et les statuts portés par aria-live restent la source d'information réelle). Encodées en
  // data URI pour rester dans un HTML autonome (aucune dépendance de fichier externe).
  const ADOC_CLARIFICATION_ILLUSTRATION = 'data:image/svg+xml;base64,';
  const ADOC_GENERATION_ILLUSTRATION = 'data:image/svg+xml;base64,';

  // Bug de clarification bloquée (repro Christophe, diagnostic console en conditions réelles) —
  // adocRenderClarityCard créait une NOUVELLE carte à chaque appel (chaque round d'un même
  // échange, ET chaque nouvelle demande) sans jamais retirer la précédente du DOM. Résultat :
  // plusieurs cartes .cc-clarity-card coexistaient, la plus ancienne poussée hors champ (top
  // très négatif) par le contenu accumulé depuis, mais toujours présente et toujours dotée de
  // son bouton "is-selected" du clic précédent — un sélecteur générique (ou tout code/outil qui
  // interroge le DOM sans se limiter à la carte réellement affichée) tombe alors sur cette carte
  // fantôme invisible plutôt que sur celle que la thérapeute voit et clique réellement. Reproduit
  // et confirmé avec preuve réelle (voir rapport de lot) : jamais plus d'une carte à la fois,
  // même patron que adocRemoveContinueChoice/adocRenderContinueChoice déjà utilisé plus haut pour
  // le même type d'élément "invite active unique".
  function adocRemoveClarityCard() {
    // Jamais se fier uniquement à la référence JS adocClarityCardEl : elle est déjà remise à
    // null dès qu'un échange se termine (transition vers la génération, cf. plus bas), BIEN
    // AVANT qu'une éventuelle nouvelle demande ultérieure ne rappelle cette fonction — un simple
    // `if (adocClarityCardEl) ...` laissait donc passer exactement la carte fantôme orpheline
    // du bug (celle d'un échange déjà complété), qui n'a alors plus aucune référence JS du tout.
    // Interroger le DOM directement garantit l'invariant réel : au plus une carte à la fois.
    // Item 62 — portée restreinte à #adoc-messages (investigation confirmée : la vraie carte de
    // clarification y est TOUJOURS ajoutée par adocRenderClarityCard, jamais ailleurs). Avant ce
    // correctif, `document.querySelectorAll` sans restriction balayait tout le document et
    // détruisait aussi le contenu de #cc-legacy-retheme-modal (markup statique du bouton "Charte",
    // en fin de <body>) qui réutilise volontairement la même classe .cc-clarity-card pour son
    // style visuel — jamais un vrai composant de clarification. Une fois détruit (markup statique,
    // jamais recréé), #cc-legacy-retheme-body disparaissait en permanence dès la première porte de
    // clarté de la session, rendant le bouton "Charte" silencieusement inopérant (reproduit et
    // confirmé, cf. rapport de lot). Les panneaux de correction/insertion de bloc (#cc-ws-doc-card)
    // partagent aussi cette classe pour le même motif de style, mais vivent hors #adoc-messages
    // eux aussi et sont de toute façon recréés à chaque clic — non affectés dans les deux cas.
    const _clarityContainer = document.getElementById('adoc-messages');
    (_clarityContainer || document).querySelectorAll('.cc-clarity-card').forEach(function (el) { el.remove(); });
    adocClarityCardEl = null;
  }

  function adocRenderClarityCard(judgment) {
    const area = document.getElementById('adoc-messages');
    if (!area) return;
    adocRemoveClarityCard();
    const card = document.createElement('div');
    card.className = 'cc-clarity-card sc-clarification-card';
    card.setAttribute('role', 'group');
    card.setAttribute('aria-label', 'Précision nécessaire avant de générer le document');

    const replies = (judgment.quick_replies || []).slice(0, 4);
    card.innerHTML =
      (judgment.understood_so_far ? '<div class="cc-clarity-understood sc-clarification-card__intro">' + adocEsc(judgment.understood_so_far) + '</div>' : '') +
      '<div class="cc-clarity-question sc-clarification-card__heading sc-icon-label">' + adocIconSvg('icon-clarify') + '<span>' + adocEsc(judgment.question || '') + '</span></div>' +
      '<img class="cc-clarity-illustration" src="' + ADOC_CLARIFICATION_ILLUSTRATION + '" alt="" aria-hidden="true">' +
      '<div class="cc-clarity-replies sc-clarification-card__choices">' +
        replies.map(function (r) {
          return '<button type="button" class="cc-clarity-reply-btn sc-clarification-choice" onclick="this.classList.add(\'is-selected\');adocClarityQuickReply(this.textContent)">' + adocEsc(r) + '</button>';
        }).join('') +
        '<button type="button" class="cc-clarity-other-btn sc-clarification-choice sc-clarification-choice--other" onclick="adocClarityFocusInput()">Autre, précisez…</button>' +
      '</div>';

    area.appendChild(card);
    area.scrollTop = area.scrollHeight;
    adocClarityCardEl = card;
    adocSetClarityPlaceholder();
  }

  // Ajoute la réponse du thérapeute à la carte affichée, pour garder une
  // trace lisible de l'échange (sans passer par adocAddMsg/adocConversations
  // — ce dialogue de cadrage n'a pas besoin de polluer la mémoire de la
  // conversation clinique, le contexte est reconstruit explicitement dans
  // adocEvaluateClarity via qaPairs).
  function adocAppendClarityAnswer(answer) {
    if (!adocClarityCardEl) return;
    const line = document.createElement('div');
    line.className = 'cc-clarity-answer';
    line.textContent = '↳ ' + answer;
    adocClarityCardEl.appendChild(line);
    const area = document.getElementById('adoc-messages');
    if (area) area.scrollTop = area.scrollHeight;
  }

  window.adocClarityQuickReply = function (text) {
    // Item 70 Volet 2 — la carte de clarté de FORMAT (palier 2) réutilise adocRenderClarityCard
    // tel quel (Option 1 actée), donc le MÊME bouton/gestionnaire — mais une réponse à CETTE
    // carte-là ne doit jamais repasser par window.adocSend()/adocMultiPlan (le plan est déjà
    // complet, seul le format manquait) : résolue à part, sans toucher au chemin ci-dessous
    // (inchangé pour toute carte de clarté de CONTENU, palier 1 — comportement STRICTEMENT
    // identique quand aucune clarté de format n'est en attente).
    if (adocFormatClarityActiveId != null) {
      _adocResolveFormatClarity(text);
      return;
    }
    const input = document.getElementById('adoc-input');
    if (!input) return;
    input.value = text;
    window.adocSend();
  };

  async function adocRunClarityGate() {
    adocThinking = true;
    const sendBtn = document.getElementById('adoc-send-btn');
    if (sendBtn) sendBtn.disabled = true;
    const typingId = adocShowTyping();
    adocUpdateTypingLabel(typingId, 'icon-clarify', 'Vérification de la demande…');

    let judgment = null;
    try {
      judgment = await adocEvaluateClarity({
        originalMessage: adocClarityOriginalMessage,
        qaPairs: adocClarityQAPairs,
        // Bug confirmé — adocClarityDocumentKind (capturé plus haut depuis
        // window.adocPendingDocumentKind, cf. commentaire à sa déclaration) n'était jusqu'ici
        // JAMAIS transmis à l'évaluateur de clarté : un type déjà cliqué explicitement sur
        // l'écran d'accueil ne l'empêchait donc pas de redemander "Quel type de document
        // souhaitez-vous produire ?". Simple passage d'information, jamais une nouvelle donnée
        // (déjà capturée et déjà utilisée plus tard par adocSendOriginal).
        explicitDocumentKind: adocClarityDocumentKind,
      });
    } catch (e) {
      // Fail-open : si l'évaluateur échoue (Worker HS, réseau, etc.), on ne bloque
      // jamais la génération — comportement identique à avant cette phase.
      console.warn('[Clarity] évaluation impossible — génération directe:', e && e.message);
    }

    if (judgment && judgment.status === 'needs_clarification' && adocClarityRound < 2) {
      adocClarityRound++;
      adocClarityLastQuestion = judgment.question || '';
      adocRemoveTyping(typingId);
      adocRenderClarityCard(judgment);
      // Phase 2 (monobloc) — même réutilisation que adocContinueGeneration/adocKeepAsIs.
      _adocResetSendState();
      adocClarityAwaitingAnswer = true;
      setTimeout(function () { document.getElementById('adoc-input')?.focus(); }, 50);
      return;
    }

    adocRemoveTyping(typingId);

    // status === 'ready', OU plafond de 2 tours atteint, OU évaluateur indisponible.
    //
    // Correctif terrain (v1.4.0) : avant, un seul finalMessage servait à la fois de
    // bulle utilisateur ET d'instruction au modèle — l'instruction technique de bandeau
    // "Hypothèses retenues" s'affichait donc verbatim comme si la thérapeute l'avait
    // tapée elle-même. Désormais deux valeurs séparées : displayMessage (bulle, courte,
    // dans ses mots) et adocClarityBannerNote (invisible, lue une fois par
    // window.adocSend pour enrichir le prompt système de CETTE génération seulement).
    let displayMessage = adocClarityOriginalMessage;
    if (adocClarityQAPairs.length) {
      const answersRecap = adocClarityQAPairs.map(function (p) { return p.answer; }).join(' ; ');
      displayMessage += ' (précisé : ' + answersRecap + ')';
    }
    const assumptions = (judgment && judgment.status === 'needs_clarification') ? (judgment.assumptions_if_proceeding || []) : [];
    adocClarityBannerNote = assumptions.length
      ? ('La demande restait partiellement ouverte après clarification. Indique clairement, ' +
         'tout au début du document, dans un bandeau visible intitulé "Hypothèses retenues :", les points ' +
         'suivants avant de poursuivre normalement : ' + assumptions.join(' ; ') + '.')
      : null;

    adocClarityAwaitingAnswer = false;
    adocClarityCardEl = null;
    adocRestoreDefaultPlaceholder(); // plafond atteint / prêt — retour au placeholder d'origine
    const input = document.getElementById('adoc-input');
    if (input) input.value = displayMessage;
    adocThinking = false; // adocSendOriginal remet lui-même ce drapeau à true
    await adocSendOriginal();
  }

  window.adocSend = async function () {
    const input = document.getElementById('adoc-input');
    const raw = (input && input.value || '').trim();
    if (!raw || adocThinking) return;

    if (adocClarityAwaitingAnswer) {
      // Cet envoi est la réponse du thérapeute à la question de clarification affichée.
      input.value = ''; adocResize(input);
      adocClarityAwaitingAnswer = false;
      adocRestoreDefaultPlaceholder(); // réponse envoyée — retour au placeholder d'origine
      adocAppendClarityAnswer(raw);
      adocClarityQAPairs.push({ question: adocClarityLastQuestion, answer: raw });
      await adocRunClarityGate();
      return;
    }

    // Nouvelle demande — réinitialise l'état de clarification et évalue avant tout.
    // Le champ est vidé tout de suite (comme avant cette phase) ; la bulle utilisateur,
    // elle, n'apparaît qu'à l'issue du jugement — c'est adocSendOriginal qui l'affichera,
    // avec le texte final (éventuellement enrichi des précisions de clarification).
    input.value = ''; adocResize(input);
    adocClarityRound = 0;
    adocClarityQAPairs = [];
    adocClarityOriginalMessage = raw;
    // Kit v2.4 (Volet 1) — capturé UNE FOIS ici (début de la demande, jamais à chaque tour de
    // clarification) puis consommé par adocSendOriginal ; window.adocPendingDocumentKind est
    // remis à null tout de suite pour ne jamais fuiter vers un envoi ultérieur sans rapport
    // (ex. bouton d'insertion rapide du chat, qui ne pose jamais cette variable).
    adocClarityDocumentKind = window.adocPendingDocumentKind || null;
    window.adocPendingDocumentKind = null;
    await adocRunClarityGate();
  };

  // ═══════════════════════════════════════════════════════════════════════
  // Phase UX-8A / UX-8A.1 — Moteur de rendu canonique par blocs (fondation du Studio)
  // ═══════════════════════════════════════════════════════════════════════
  // Prend un ClinicalDocument structuré (conforme à schemas/clinical-document.schema.json)
  // + un SourceSnapshot, résout son RenderManifest (renderManifestId → jetons de rendu),
  // et produit un rendu HTML. Couvre les deux pilotes (fiche, carrousel) avec un modèle
  // minimal chacun — tableau/script/liens restent sur l'ancien moteur (génération HTML
  // directe par le modèle) via rendererModeByDocumentKind.
  //
  // UX-8A.1 (lot correctif, audit indépendant confirmé point par point) :
  //  - tout document/manifeste/snapshot est validé contre les VRAIS schémas JSON Schema
  //    (ajv, vendorisé localement) avant d'atteindre le renderer — rejeté sinon ;
  //  - le RenderManifest est réellement résolu et consommé (tokensSnapshotId → jetons
  //    appliqués au rendu via des variables CSS, changer tokensSnapshotId change le rendu) ;
  //  - contentChecksum est réellement recalculé (SHA-256 natif, Web Crypto) et comparé ;
  //  - l'affichage des citations dérive strictement de validation.citationLinks (jamais de
  //    citationIds brut, non validé) et couvre tous les types de blocs porteurs de texte ;
  //  - l'export est réellement bloqué (html:null) si le contrôle qualité l'interdit.

  // Registres résolus depuis les blocs <script type="application/json"> embarqués en tête
  // de fichier (mêmes valeurs que fixtures/render-manifest-default.json et
  // fixtures/tokens-studio-clinique-default-v1.json — voir commentaire à leur emplacement).
  window.adocRenderManifests = JSON.parse(document.getElementById('adoc-sc-render-manifests').textContent);
  window.adocTokensSnapshots = JSON.parse(document.getElementById('adoc-sc-tokens-snapshots').textContent);

  // rendererModeByDocumentKind décrit une capacité réelle et déjà éprouvée : ce que le MOTEUR DE
  // RENDU (adocRenderClinicalDocument, appelé directement avec un ClinicalDocument déjà en main)
  // sait produire. 'structured' pour carrousel est exact ici — adocRenderCarrouselHTML existe et
  // fonctionne (couvert depuis le lot fondateur UX-8A) — retirer cette valeur casserait ce rendu
  // déjà validé, jamais souhaité. Item 72 construction — 'structured' pour script est désormais
  // exact aussi : adocRenderScriptHTML existe et est branché dans adocRenderClinicalDocument
  // (vérifié avant ce flip, jamais l'inverse — piège nommé par l'investigation item 72 point 5 :
  // activer la génération sans le rendu produit un échec silencieux, repli systématique invisible).
  // Item 73 construction — 'structured' pour tableau est désormais exact aussi :
  // adocRenderTableauHTML existe et est branché (même vigilance que Script — vérifié avant ce
  // flip). L'export xlsx (item 67) reste hors de ce périmètre : exclu explicitement au site
  // d'appel de la tentative structurée (cf. `!(_structuredAttemptKind === 'tableau' &&
  // plan?._explicitXlsxRequested)`), jamais concerné par ce registre de RENDU.
  // Item 74 construction — DERNIER TYPE DU CATALOGUE. 'structured' pour liens est désormais exact
  // aussi : adocRenderLiensHTML existe et est branché (même vigilance que Script/Tableau —
  // vérifié avant ce flip). Aucun mécanisme d'export concurrent à exclure ici (contrairement à
  // Tableau/xlsx, confirmé par l'investigation item 74 point 4) — câblage aussi simple que Script.
  window.rendererModeByDocumentKind = { fiche: 'structured', carrousel: 'structured', tableau: 'structured', script: 'structured', liens: 'structured' };
  function adocGetRendererMode(documentKind) {
    return (window.rendererModeByDocumentKind && window.rendererModeByDocumentKind[documentKind]) || 'legacy';
  }
  // Audit systémique (Priorité 8.3) — registre séparé et honnête de rendererModeByDocumentKind
  // ci-dessus (qui décrit une capacité de RENDU réelle, jamais concernée par cette question) :
  // celui-ci dit quels types la GÉNÉRATION automatique (adocSend) tente réellement via le moteur
  // structuré. Item 69 construction — carrousel rejoint fiche (orchestrateur générique
  // adocGenerateStructuredDocument, cf. ADOC_STRUCTURED_PROFILES) ; liens reste à false,
  // non touché ce lot (0D — chantier séparé, aucun schéma de bloc structuré pour lui). Item 72
  // construction — script rejoint fiche/carrousel (ADOC_STRUCTURED_PROFILES.script), ACTIVÉ EN
  // MÊME TEMPS que rendererModeByDocumentKind.script ci-dessus, jamais l'un sans l'autre (piège
  // nommé par l'investigation item 72 point 5). Item 73 construction — tableau rejoint à son tour
  // (ADOC_STRUCTURED_PROFILES.tableau), ACTIVÉ EN MÊME TEMPS que rendererModeByDocumentKind.tableau
  // ci-dessus — l'exclusion xlsx (site d'appel) reste le seul garde-fou supplémentaire propre à
  // ce type, absent pour Script. Item 74 construction — liens rejoint à son tour et clôt le
  // catalogue (ADOC_STRUCTURED_PROFILES.liens, adocRenderLiensHTML), ACTIVÉ EN MÊME TEMPS que
  // rendererModeByDocumentKind.liens ci-dessus — aucun garde-fou supplémentaire type xlsx requis
  // ici (confirmé par l'investigation item 74 point 4), câblage aussi direct que Script.
  window.adocStructuredGenerationWiredByDocumentKind = { fiche: true, carrousel: true, tableau: true, script: true, liens: true };

  // ── Validation JSON Schema réelle (ajv, vendorisé localement — vendor/ajv2020.min.js) ──
  let _adocAjvValidators = null;
  function adocInitSchemaValidators() {
    if (_adocAjvValidators) return _adocAjvValidators;
    if (typeof window.Ajv2020 !== 'function') {
      console.warn('[UX-8A.1] ajv (vendor/ajv2020.min.js) non chargé — validation de schéma indisponible.');
      return null;
    }
    const ajv = new window.Ajv2020({ strict: true, allErrors: true });
    if (typeof window.ajvAddFormats === 'function') window.ajvAddFormats(ajv);
    const schemasEl = document.getElementById('adoc-sc-schemas');
    const schemas = JSON.parse(schemasEl.textContent);
    Object.keys(schemas).forEach(id => ajv.addSchema(schemas[id], id));
    _adocAjvValidators = {
      clinicalDocument: ajv.getSchema('clinical-document.schema.json'),
      renderManifest: ajv.getSchema('render-manifest.schema.json'),
      sourceSnapshot: ajv.getSchema('source-snapshot.schema.json'),
      citation: ajv.getSchema('citation.schema.json'),
      block: ajv.getSchema('block.schema.json'),
    };
    return _adocAjvValidators;
  }
  // CORRECTIF A18 (audit Codex) — {valid:true, skipped:true} restait un état DISTINCT de
  // {valid:true} (utile pour du diagnostic), mais les 3 sites d'appel qui inspectent .skipped
  // le traitaient comme "validé avec succès" (`!check.valid && !check.skipped`), jamais comme un
  // échec — un document réellement invalide passait alors sans que personne ne le sache, si AJV
  // n'avait pas pu charger. Message d'erreur désormais explicite dans ce cas (au lieu d'un
  // tableau vide qui aurait produit un message tronqué "Validation de schéma échouée (kind) : "
  // sans aucun détail) : la forme du retour ne change pas, seul errors est rempli.
  function adocValidateSchema(kind, obj) {
    const validators = adocInitSchemaValidators();
    if (!validators || !validators[kind])
      return { valid: true, errors: ['AJV (vendor/ajv2020.min.js) non chargé — validation de schéma impossible.'], skipped: true };
    const fn = validators[kind];
    const valid = fn(obj);
    return { valid, errors: valid ? null : (fn.errors || []).map(e => (e.instancePath || '/') + ' ' + e.message) };
  }
  function AdocSchemaValidationError(kind, errors) {
    const e = new Error('Validation de schéma échouée (' + kind + ') : ' + (errors || []).join(' | '));
    e.name = 'AdocSchemaValidationError';
    e.kind = kind;
    e.schemaErrors = errors;
    return e;
  }

  // ── Résolution du RenderManifest et des jetons (point 3 : réellement consommés) ──
  function adocResolveRenderManifest(doc, renderManifestOverride) {
    const manifest = renderManifestOverride || (window.adocRenderManifests && window.adocRenderManifests[doc.renderManifestId]);
    if (!manifest) {
      throw AdocSchemaValidationError('render-manifest.schema.json', ['renderManifestId "' + doc.renderManifestId + '" introuvable dans window.adocRenderManifests']);
    }
    const check = adocValidateSchema('renderManifest', manifest);
    // CORRECTIF A18 — échoue désormais fermé si AJV n'a pas pu charger (check.skipped), jamais
    // traité comme un succès silencieux (cf. commentaire d'adocValidateSchema).
    if (!check.valid || check.skipped) throw AdocSchemaValidationError('render-manifest.schema.json', check.errors);
    return manifest;
  }
  function adocResolveTokens(renderManifest) {
    const tokens = window.adocTokensSnapshots && window.adocTokensSnapshots[renderManifest.tokensSnapshotId];
    if (!tokens) {
      throw AdocSchemaValidationError('tokens-snapshot', ['tokensSnapshotId "' + renderManifest.tokensSnapshotId + '" introuvable dans window.adocTokensSnapshots']);
    }
    return tokens;
  }
  function adocTokensToCSSVars(tokens) {
    const c = tokens.colors || {};
    const t = tokens.typography || {};
    const pairs = {
      '--adoc-sc-body-color': c.ink,
      '--adoc-sc-heading-color': c.petrol950,
      '--adoc-sc-callout-info-bg': c.petrol100,
      '--adoc-sc-callout-info-border': c.petrol800,
      '--adoc-sc-callout-warning-bg': c.terracotta100,
      '--adoc-sc-callout-warning-border': c.terracotta700,
      '--adoc-sc-cite-color': c.terracotta700,
      '--adoc-sc-quote-border': c.terracotta700,
      '--adoc-sc-quote-color': c.petrol900,
      '--adoc-sc-table-header-bg': c.petrol100,
      '--adoc-sc-table-header-color': c.petrol950,
      '--adoc-sc-table-border': c.stone300,
      '--adoc-sc-card-border': c.stone300,
      '--adoc-sc-card-bg': c.paper,
      '--adoc-sc-heading-font': t.headingFontFamily,
      '--adoc-sc-body-font': t.bodyFontFamily,
      // Item 63e construction — densité de texte (interligne), overlay optionnel posé par
      // adocBuildRenderManifestForBrandKit (jamais un champ de adocBrandKitToTokensSnapshot :
      // une densité de lecture n'est pas une propriété de charte). Absent (null) pour tout
      // tokensSnapshot antérieur à ce lot ou n'ayant jamais reçu ce réglage → filtré par
      // .filter() ci-dessous, jamais émis → la règle CSS .adoc-sc-doc garde son repli 1.65,
      // rendu visuel strictement inchangé (rétrocompatibilité).
      '--adoc-sc-line-height': t.lineHeight,
    };
    return Object.keys(pairs).filter(k => pairs[k] != null).map(k => k + ':' + pairs[k] + ';').join('');
  }

  // ── SHA-256 réel (Web Crypto native, pas d'implémentation maison) ──
  async function adocComputeSHA256Hex(text) {
    const data = new TextEncoder().encode(text == null ? '' : String(text));
    const digest = await crypto.subtle.digest('SHA-256', data);
    return Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, '0')).join('');
  }

  // ── UX-8B Lot 2 — pont entre le schéma générique brand_kits (D1 : primary/accent/
  // background/text/success/warning/critical) et le vocabulaire fin déjà consommé par
  // adocTokensToCSSVars (petrol950/900/800/100, terracotta700/600/100, ink, stone300, paper…).
  // Aucune modification d'adocTokensToCSSVars ni du chrome : uniquement une traduction, côté
  // jetons du DOCUMENT. Choix de correspondance assumés (à documenter dans le rapport de lot,
  // pas des bugs) :
  //  - terracotta700 ← warning : pour la charte 1 (seed migration 0001), warning=#8a3f29 est
  //    strictement identique à l'ancien terracotta700 en dur — ce choix préserve donc à
  //    l'identique le rendu déjà existant des callouts d'avertissement pour la charte par
  //    défaut. Les citations (qui réutilisaient aussi terracotta700) glissent légèrement de
  //    teinte avec ce même mappage — décalage mineur assumé, pas une régression du lot 1 (qui
  //    ne câblait rien au rendu).
  //  - petrol950/900/800 (3 teintes distinctes) collapsent sur la seule valeur `primary` du
  //    nouveau schéma, avec des teintes claires/sombres synthétisées par mélange — cohérent
  //    avec la simplification volontaire du schéma générique (UX-8B), pas une perte accidentelle.
  function adocMixHexColor(hexA, hexB, ratio) {
    const parse = (hex) => {
      const h = String(hex).replace('#', '');
      const full = h.length === 3 ? h.split('').map((c) => c + c).join('') : h;
      return [0, 2, 4].map((i) => parseInt(full.substr(i, 2), 16) || 0);
    };
    const a = parse(hexA), b = parse(hexB);
    const mix = (x, y) => Math.round(x + (y - x) * ratio);
    return '#' + [0, 1, 2].map((i) => mix(a[i], b[i]).toString(16).padStart(2, '0')).join('');
  }

  function adocBrandKitToTokensSnapshot(brandKit) {
    const c = brandKit.colors || {};
    const t = brandKit.typography || {};
    const primary = c.primary || '#102f31';
    const accent = c.accent || '#9b4e36';
    const background = c.background || '#f6f2ea';
    const text = c.text || '#273331';
    const warning = c.warning || accent;
    return {
      tokensSnapshotId: 'brandkit-' + brandKit.id + '-tokens-v' + (brandKit.version || 1),
      colors: {
        petrol950: primary,
        petrol900: adocMixHexColor(primary, '#000000', 0.12),
        petrol800: adocMixHexColor(primary, '#ffffff', 0.18),
        petrol100: adocMixHexColor(primary, '#ffffff', 0.88),
        terracotta700: warning,
        terracotta600: accent,
        terracotta100: adocMixHexColor(warning, '#ffffff', 0.85),
        ink: text,
        muted: adocMixHexColor(text, background, 0.45),
        stone400: adocMixHexColor(text, background, 0.6),
        stone300: adocMixHexColor(text, background, 0.72),
        stone200: adocMixHexColor(text, background, 0.85),
        ivory: background,
        paper: adocMixHexColor(background, '#ffffff', 0.4),
        white: '#ffffff',
      },
      typography: {
        headingFontFamily: t.headingFont || '"Source Serif 4", Georgia, serif',
        bodyFontFamily: t.bodyFont || '"IBM Plex Sans", system-ui, sans-serif',
      },
    };
  }

  // Sérialisation JSON canonique (clés triées, sans espace superflu) — exigée par
  // render-manifest.schema.json pour le calcul de manifestChecksum.
  function adocCanonicalJSONStringify(value) {
    if (value === null || typeof value !== 'object') return JSON.stringify(value);
    if (Array.isArray(value)) return '[' + value.map(adocCanonicalJSONStringify).join(',') + ']';
    const keys = Object.keys(value).sort();
    return '{' + keys.map((k) => JSON.stringify(k) + ':' + adocCanonicalJSONStringify(value[k])).join(',') + '}';
  }

  // Construit un RenderManifest réel (checksum réellement calculé, pas de valeur figée) pour
  // une charte choisie au moment de la demande. Reprend templateRef/rendererVersion du
  // manifeste déjà associé au document (jamais réinventés ici) — seuls brandKitRef,
  // tokensSnapshotId et assetsSnapshotId changent, exactement ce que permet déjà
  // adocResolveRenderManifest(doc, renderManifestOverride) sans aucune modification du moteur
  // de rendu canonique.
  async function adocBuildRenderManifestForBrandKit(doc, brandKit, densityId) {
    const baseManifest = window.adocRenderManifests && window.adocRenderManifests[doc.renderManifestId];
    const templateRef = (baseManifest && baseManifest.templateRef) || { id: 'fiche-editoriale', version: 1 };
    const rendererVersion = (baseManifest && baseManifest.rendererVersion) || '1.0.0';
    const tokens = adocBrandKitToTokensSnapshot(brandKit);
    // Item 63e construction — densité de texte, overlay optionnel posé ICI (jamais dans
    // adocBrandKitToTokensSnapshot : une densité de lecture n'est pas une propriété de charte,
    // même raisonnement que le choix de police côté ancien moteur, non plus stocké dans le brand
    // kit). 3ᵉ paramètre optionnel, rétrocompatible : l'appel existant depuis
    // adocResolveBrandKitForGeneration (2 arguments, jamais modifié) continue de produire des
    // tokens sans lineHeight, exactement comme avant ce lot.
    const densityPreset = ADOC_DENSITY_PRESETS.find(function (p) { return p.id === densityId; });
    if (densityPreset && densityPreset.id !== 'keep' && densityPreset.structuredLineHeight != null) {
      tokens.typography = Object.assign({}, tokens.typography, { lineHeight: densityPreset.structuredLineHeight });
    }
    window.adocTokensSnapshots = window.adocTokensSnapshots || {};
    window.adocTokensSnapshots[tokens.tokensSnapshotId] = tokens;
    const manifestBase = {
      id: 'manifest-brandkit-' + brandKit.id + '-' + Date.now(),
      schemaVersion: 1,
      rendererVersion: rendererVersion,
      templateRef: templateRef,
      brandKitRef: { id: brandKit.id, version: brandKit.version || 1 },
      tokensSnapshotId: tokens.tokensSnapshotId,
      assetsSnapshotId: null,
      createdAt: new Date().toISOString(),
    };
    const checksumHex = await adocComputeSHA256Hex(adocCanonicalJSONStringify(manifestBase));
    return Object.assign({}, manifestBase, { manifestChecksum: 'sha256:' + checksumHex });
  }

  // ── UX-8B Lot 2 — liste réelle des chartes, jamais codée en dur côté client (GET /brand-kits,
  // même clé X-API-Key que toutes les autres routes protégées). Un échec réseau/serveur ne
  // bloque jamais l'écran d'accueil : la charte par défaut reste utilisable via le fallback
  // déjà en place dans adocResolveBrandKitForGeneration (générateur de manifeste) plus bas.
  const ADOC_DEFAULT_BRAND_KIT_ID = '00000000-0000-4000-8000-000000000001';
  let _adocBrandKitsCache = null;
  // Charte choisie pour la demande EN COURS (capturée par le listener conseiller-clinique:start
  // ci-dessous) — jamais un réglage global : remise à '' n'importe quand par une nouvelle demande.
  let adocActiveBrandKitId = '';
  // Parité 0F (monobloc) — capturé au même endroit, même cycle de vie que adocActiveBrandKitId
  // ci-dessus, mais consommé UNIQUEMENT par l'application automatique de la charte à l'ancien
  // moteur (adocFinalizeGeneration) : true seulement si la valeur ci-dessus reflète un vrai
  // geste de la thérapeute (changement manuel du sélecteur, ou préférence sauvegardée d'un choix
  // passé) — jamais la présélection mécanique du premier élément d'une liste par défaut (cf.
  // window.cc_brandKitSelectionIsExplicit). Le moteur structuré n'y touche jamais.
  let adocActiveBrandKitExplicit = false;
  function adocFetchBrandKits() {
    const workerUrl = adocGetWorkerUrl();
    return fetch(workerUrl + '/brand-kits', { headers: { 'X-API-Key': adocGetApiKey() } })
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error('HTTP ' + r.status))))
      .then((data) => {
        const kits = Array.isArray(data.brand_kits) ? data.brand_kits : [];
        _adocBrandKitsCache = kits;
        window._adocBrandKits = kits;
        if (typeof window.setConseillerCliniqueBrandKits === 'function' && kits.length) {
          window.setConseillerCliniqueBrandKits(kits);
        }
        // UX-8B Lot 3 — le bouton "Retirer" ne doit jamais apparaître sur les 2 chartes par
        // défaut (Lot 1/2) ; à réévaluer à chaque rafraîchissement (chargement initial, après
        // import, après retrait), pas seulement sur un changement manuel de sélection.
        adocUpdateBrandKitRemoveButtonVisibility();
        return kits;
      })
      .catch((e) => {
        console.warn('[UX-8B] GET /brand-kits indisponible, charte par défaut utilisée au besoin.', e);
        return [];
      });
  }
  function adocGetBrandKitById(id) {
    const cached = (_adocBrandKitsCache || []).find((k) => k.id === id);
    if (cached) return Promise.resolve(cached);
    if (!id) return Promise.resolve(null);
    const workerUrl = adocGetWorkerUrl();
    return fetch(workerUrl + '/brand-kits/' + encodeURIComponent(id), { headers: { 'X-API-Key': adocGetApiKey() } })
      .then((r) => (r.ok ? r.json() : null))
      .catch(() => null);
  }

  // Point d'appel unique du call site de génération (point 3 du lot — « le vrai test »).
  // Résout la charte réellement choisie pour CETTE demande (adocActiveBrandKitId, capturé par
  // le listener conseiller-clinique:start) et construit un RenderManifest override réel. Ne
  // déclenche JAMAIS de nouvelle recherche RAG : ne touche qu'à un GET /brand-kits/:id déjà en
  // cache la plupart du temps, et ne lit/n'écrit jamais doc.blocks ni sourceSnapshot. Repli
  // silencieux sur la charte par défaut (aucun override construit → moteur canonique inchangé)
  // si la charte demandée est introuvable/indisponible — jamais un blocage de la génération.
  async function adocResolveBrandKitForGeneration(doc) {
    const requestedId = adocActiveBrandKitId || ADOC_DEFAULT_BRAND_KIT_ID;
    try {
      const brandKit = await adocGetBrandKitById(requestedId);
      if (!brandKit || !brandKit.id) return { renderManifestOverride: null, brandKitName: null };
      const renderManifestOverride = await adocBuildRenderManifestForBrandKit(doc, brandKit);
      return { renderManifestOverride, brandKitName: brandKit.name || null };
    } catch (e) {
      console.warn('[UX-8B] Résolution de charte impossible, repli sur la charte par défaut du manifeste.', e);
      return { renderManifestOverride: null, brandKitName: null };
    }
  }

  // ═══════════════════════════════════════════════════════════════════════
  // Modernisation ancien moteur — personnalisation des couleurs d'un document déjà généré,
  // en un clic (type Gamma/Canva). PORTÉE VOLONTAIREMENT LIMITÉE, décision actée : UNIQUEMENT
  // les couleurs, UNIQUEMENT fmt==='html' (jamais html-visual/pdf/zip — ceux-ci ne conservent
  // pas de art.html retouchable, cf. rapport), UNIQUEMENT le moteur legacy (jamais un document
  // du moteur structuré, qui a déjà son propre système de charte à la génération).
  //
  // Investigation préalable (adocBuildSystemPrompt, ~ligne 4437) : le prompt système impose au
  // modèle un bloc littéral ":root { --mer:#1f5053; --deep:#102f31; --vert-sauge:#c9c3b8;
  // --beige:#ddd7cc; --sable:#f6f2ea; --surf:#f6f2ea; --text:#273331; --muted:#5d6966;
  // --blanc:#FFFFFF }" — ces 9 variables sont donc bien isolables et remplaçables après coup,
  // sans toucher au reste du HTML. Réutilise EXACTEMENT adocBrandKitToTokensSnapshot (déjà
  // existant pour le moteur structuré) pour dériver les nouvelles valeurs — jamais un second
  // système de couleurs parallèle.
  var ADOC_LEGACY_ROOT_VARS = ['mer', 'deep', 'vert-sauge', 'beige', 'sable', 'surf', 'text', 'muted', 'blanc'];

  // Correspondance entre les 9 variables de l'ancien moteur et les tokens sémantiques déjà
  // dérivés d'une charte (adocBrandKitToTokensSnapshot) — un choix de mapping documenté dans le
  // rapport, pas une évidence : --deep (H1/H2, en-têtes) est la couleur la plus sombre/dominante
  // (petrol950, "primary"), --mer (titres, bordures, accents) sa variante plus claire
  // (petrol800), --vert-sauge/--beige des tons neutres clairs (stone300/200), --sable/--surf le
  // fond général (ivory), --text/--muted le texte (ink/muted), --blanc toujours blanc pur,
  // indépendant de la charte (fond des zones de texte, jamais une couleur de marque).
  function adocBuildLegacyPaletteFromBrandKit(brandKit) {
    const t = adocBrandKitToTokensSnapshot(brandKit);
    return {
      mer: t.colors.petrol800,
      deep: t.colors.petrol950,
      'vert-sauge': t.colors.stone300,
      beige: t.colors.stone200,
      sable: t.colors.ivory,
      surf: t.colors.ivory,
      text: t.colors.ink,
      muted: t.colors.muted,
      blanc: '#FFFFFF',
    };
  }

  // Vérifie que le document porte bien le bloc :root attendu, avec ses 9 variables — jamais une
  // tentative silencieuse de remplacement si le modèle n'a pas respecté la consigne pour CE
  // document précis (aucune garantie de conformité, cf. rapport — vérification en conditions
  // réelles non faisable dans cet environnement, pas d'accès à l'API Anthropic réelle).
  function adocParseLegacyRootVars(html) {
    const rootMatch = /:root\s*\{([^}]*)\}/.exec(html || '');
    if (!rootMatch) return null;
    const body = rootMatch[1];
    const allFound = ADOC_LEGACY_ROOT_VARS.every(function (name) {
      return new RegExp('--' + name + '\\s*:\\s*[^;}]+', 'i').test(body);
    });
    return allFound ? { blockBody: body } : null;
  }

  // Remplace UNIQUEMENT la valeur de chacune des 9 variables, jamais rien d'autre dans le
  // document (contenu, structure, scripts) — une déclaration "--mer:" n'apparaît nulle part
  // ailleurs qu'à sa définition dans :root (un usage s'écrit "var(--mer)", jamais "--mer:"),
  // donc un remplacement non ancré au bloc :root reste sûr et plus simple qu'un découpage
  // manuel du bloc.
  function adocApplyLegacyRootVars(html, palette) {
    let newHtml = html;
    ADOC_LEGACY_ROOT_VARS.forEach(function (name) {
      const value = palette[name];
      if (!value) return;
      newHtml = newHtml.replace(new RegExp('(--' + name + '\\s*:\\s*)[^;}]+', 'i'), '$1' + value);
    });
    return newHtml;
  }

  // Orchestrateur — retourne { ok:false } sans rien modifier si le bloc :root attendu n'est pas
  // retrouvé (document antérieur à ce lot, ou modèle n'ayant pas respecté la consigne cette
  // fois-là) : jamais une tentative partielle qui laisserait croire à un changement qui n'a pas
  // eu lieu.
  function adocRethemeLegacyHtml(html, brandKit) {
    const rootInfo = adocParseLegacyRootVars(html);
    if (!rootInfo) return { ok: false, html: html };
    const palette = adocBuildLegacyPaletteFromBrandKit(brandKit);
    return { ok: true, html: adocApplyLegacyRootVars(html, palette) };
  }

  // Parité 0F (monobloc) — appelée depuis adocFinalizeGeneration (jamais un nouveau chemin de
  // fin de génération : un simple appel de plus À L'INTÉRIEUR d'un point de sortie déjà couvert
  // par _adocResetSendState() côté appelant). Réutilise adocRethemeLegacyHtml/adocGetBrandKitById
  // TELS QUELS (jamais une nouvelle logique de teinte dupliquée) — même contrat que le panneau
  // manuel (adocPreviewLegacyRetheme/adocConfirmLegacyRetheme) : { ok:false } sans rien modifier
  // si le gabarit couleur n'est pas retrouvé, charte introuvable ⇒ document livré tel quel,
  // jamais un blocage ni une exception qui remonterait à l'appelant (celui-ci l'attrape déjà,
  // mais autant ne jamais en émettre).
  async function adocApplyBrandKitToLegacyArtifact(storeKey, brandKitId) {
    const art = window._adocArtifacts && window._adocArtifacts[storeKey];
    if (!art || !art.html) return;
    const brandKit = await adocGetBrandKitById(brandKitId);
    if (!brandKit || !brandKit.id) return;
    const colorResult = adocRethemeLegacyHtml(art.html, brandKit);
    if (!colorResult.ok) return;
    if (art.blobUrl) URL.revokeObjectURL(art.blobUrl);
    art.html = colorResult.html;
    art.blobUrl = URL.createObjectURL(new Blob([art.html], { type: 'text/html;charset=utf-8' }));
    art._adocBrandKitName = brandKit.name || null;
  }

  // ═══════════════════════════════════════════════════════════════════════
  // LOT 11 — Changement de police d'un document legacy, en un clic (même geste que le
  // reteintage de couleurs ci-dessus). Investigation préalable (LOT 11, rapport séparé) :
  // contrairement au bloc :root des couleurs (un GABARIT EXACT donné au modèle, valeurs en
  // dur à recopier), l'instruction de police est une DIRECTIVE EN PROSE ("Police principale :
  // IBM Plex Sans… titres en Source Serif 4") — le modèle est libre de la traduire en CSS de
  // façons différentes d'une génération à l'autre (sélecteurs groupés h1,h2,h3{...}, :is(),
  // indirection par variable CSS…). Un détecteur cherchant une STRUCTURE CSS précise
  // (body{font-family}/h1{font-family} isolés) manque donc une part significative des
  // documents pourtant parfaitement conformes au prompt — vérifié sur 5 variantes construites,
  // 3 manquées. En revanche, les deux NOMS DE POLICE LITTÉRAUX ("IBM Plex Sans", "Source
  // Serif 4") apparaissent, eux, toujours en toutes lettres quelque part dans le <style> —
  // vérifié sur les 5 mêmes variantes, y compris l'indirection par variable. D'où : un
  // remplacement par RECHERCHE LITTÉRALE DU TEXTE, jamais par structure CSS.
  // ═══════════════════════════════════════════════════════════════════════

  const ADOC_LEGACY_DEFAULT_BODY_FONT = 'IBM Plex Sans';
  const ADOC_LEGACY_DEFAULT_HEADING_FONT = 'Source Serif 4';

  // Liste curatée — aucune liste de polices n'existait déjà dans ce fichier pour un choix
  // utilisateur (vérifié explicitement lors de l'investigation ; adocBrandKitImport extrait une
  // police depuis un PDF importé, ce n'est pas un menu de choix). Sélection sobre, cohérente
  // avec l'identité pétrole/terracotta déjà établie : une police de titre serif éditoriale +
  // une police de corps sans-serif humaniste, jamais l'inverse. 'keep' n'applique aucun
  // remplacement (la police du document reste exactement ce qu'elle était).
  const ADOC_LEGACY_FONT_PAIRS = [
    { id: 'keep', label: 'Ne pas changer la police', bodyFont: null, headingFont: null, googleFontsHref: null },
    { id: 'default', label: 'Police par défaut du Studio — IBM Plex Sans / Source Serif 4', bodyFont: 'IBM Plex Sans', headingFont: 'Source Serif 4',
      googleFontsHref: 'https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=Source+Serif+4:opsz,wght@8..60,600&display=swap' },
    { id: 'inter-lora', label: 'Inter / Lora — clair et structuré', bodyFont: 'Inter', headingFont: 'Lora',
      googleFontsHref: 'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Lora:wght@500;600;700&display=swap' },
    { id: 'public-merriweather', label: 'Public Sans / Merriweather — chaleureux et lisible', bodyFont: 'Public Sans', headingFont: 'Merriweather',
      googleFontsHref: 'https://fonts.googleapis.com/css2?family=Public+Sans:wght@400;500;600;700&family=Merriweather:wght@400;700&display=swap' },
    { id: 'work-crimson', label: 'Work Sans / Crimson Pro — académique sobre', bodyFont: 'Work Sans', headingFont: 'Crimson Pro',
      googleFontsHref: 'https://fonts.googleapis.com/css2?family=Work+Sans:wght@400;500;600;700&family=Crimson+Pro:wght@500;600;700&display=swap' },
    { id: 'mulish-baskerville', label: 'Mulish / Libre Baskerville — doux et éditorial', bodyFont: 'Mulish', headingFont: 'Libre Baskerville',
      googleFontsHref: 'https://fonts.googleapis.com/css2?family=Mulish:wght@400;500;600;700&family=Libre+Baskerville:wght@400;700&display=swap' },
    { id: 'karla-playfair', label: 'Karla / Playfair Display — élégant contemporain', bodyFont: 'Karla', headingFont: 'Playfair Display',
      googleFontsHref: 'https://fonts.googleapis.com/css2?family=Karla:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap' },
  ];

  // ═══════════════════════════════════════════════════════════════════════
  // Item 63e construction — densité de texte (interligne), 3ᵉ réglage du même geste "un clic"
  // (couleurs + police déjà en place ci-dessus, jamais un troisième panneau séparé). Investigation
  // préalable : contrairement aux couleurs (gabarit :root exact) et à la police (noms littéraux
  // déjà mandatés par la charte), AUCUNE convention de mise en page n'était jusqu'ici imposée au
  // modèle pour l'ancien moteur ("Layout editorial professionnel", instruction en prose, aucune
  // valeur ni ancrage détectable) — vérifié par lecture complète de adocBuildSystemPrompt/
  // _execContext. Un simple ajout de '--adoc-line-height' à la classe de ponctuation... pardon,
  // à la liste ADOC_LEGACY_ROOT_VARS des couleurs aurait, à tort, transformé cette 10ᵉ variable en
  // condition bloquante pour le reteintage COULEUR de tout document déjà généré avant ce lot (qui
  // ne l'a jamais). Traité ici comme un mécanisme INDÉPENDANT, troisième et dernier, même schéma
  // que la police (LOT 11) : un ancrage propre, ajouté au même gabarit :root que les couleurs
  // (donc désormais mandaté à la génération, cf. adocBuildSystemPrompt), détecté/appliqué par ses
  // propres fonctions dédiées, jamais mélangé aux 9 variables de couleur.
  //
  // Valeurs "normal" choisies pour préserver EXACTEMENT le rendu actuel de chaque moteur si la
  // thérapeute choisit "Normal" (pas seulement "Ne pas changer") : 1.65 côté structuré (déjà la
  // valeur codée en dur de .adoc-sc-doc), 1.7 côté legacy (nouvelle valeur mandatée à la
  // génération, aucune valeur préexistante à préserver pour ce moteur — choix assumé, documenté
  // dans le rapport de lot, pas une évidence). "Resserré"/"Aéré" sont des écarts modérés (±0.25 à
  // ±0.3) valables pour les deux moteurs, jamais identiques en valeur absolue (chaque moteur garde
  // sa propre base), toujours identiques dans leur INTENTION (même 4 choix proposés partout).
  const ADOC_DENSITY_PRESETS = [
    { id: 'keep', label: 'Ne pas changer la densité', legacyLineHeight: null, structuredLineHeight: null },
    { id: 'compact', label: 'Resserré', legacyLineHeight: 1.45, structuredLineHeight: 1.4 },
    { id: 'normal', label: 'Normal', legacyLineHeight: 1.7, structuredLineHeight: 1.65 },
    { id: 'airy', label: 'Aéré', legacyLineHeight: 1.95, structuredLineHeight: 1.85 },
  ];

  // 57f — Shared editing gestures; structured JSON and legacy HTML keep separate persistence.
  var ADOC_DIRECT_TYPES = ['heading', 'paragraph', 'quote', 'callout', 'list', 'table'];
  var ADOC_DIRECT_STYLE_FIELDS = {
    fontFamily: 'font-family', color: 'color', backgroundColor: 'background-color',
    fontSizePt: 'font-size', fontWeight: 'font-weight', fontStyle: 'font-style',
    textDecoration: 'text-decoration', textAlign: 'text-align', lineHeight: 'line-height',
    letterSpacing: 'letter-spacing', marginTop: 'margin-top', marginBottom: 'margin-bottom',
    textIndent: 'text-indent', textTransform: 'text-transform', borderColor: 'border-color', borderWidth: 'border-width'
  };
  // LOT D — titre de couverture (doc.title, racine du ClinicalDocument, 4 documentKind qui
  // partagent la même bannière — Fiche/Script/Tableau/Liens, cf. Lot B) et titre de carte
  // Carrousel (card.content.title) ne vivent jamais dans doc.blocks[] (investigation item 68) :
  // un seul point d'entrée partagé (jamais cinq correctifs séparés, régression #6) pour les
  // reconnaître comme "corrigibles" par le même panneau que n'importe quel bloc. Identifiants
  // réservés ('root:doc-title', 'root:card-title:<cardId>') posés en id= sur l'élément rendu
  // (adocRenderFicheHTML et consorts, adocRenderCardHTML) pour que document.getElementById
  // (adocEditorContext) les résolve exactement comme un bloc normal, sans mécanisme séparé.
  function adocRootFieldRef(doc, id) {
    if (!doc || !id) return null;
    if (id === 'root:doc-title') return { get: function () { return doc.title; }, set: function (v) { doc.title = v; } };
    if (id.indexOf('root:card-title:') === 0) {
      const cardId = id.slice('root:card-title:'.length);
      const card = (doc.blocks || []).find(function (c) { return c.id === cardId; });
      if (card) return { get: function () { return card.content.title; }, set: function (v) { card.content.title = v; } };
    }
    return null;
  }
  function adocFindEditableBlock(doc, id) {
    const rootRef = adocRootFieldRef(doc, id);
    // Niveau 1 par convention (jamais recalculé depuis un rendu existant, ni deviné) : ces
    // titres ne sont jamais des .adoc-sc-block réels, adocBlockContentText/adocDescribeBlockContent
    // n'utilisent que .text pour 'heading' — level ne sert ici qu'au clamp d'affichage existant.
    if (rootRef) return { id: id, type: 'heading', content: { text: rootRef.get() || '', level: 1 }, citationIds: [], validation: {} };
    function walk(blocks) { for (const b of blocks || []) { if (b.id === id) return b; const child = walk(b.content && b.content.blocks); if (child) return child; } }
    return walk(doc && doc.blocks);
  }
  // Item 64 construction — court aperçu du bloc sélectionné, affiché en tête du panneau de
  // correction (utile même redevenu contextuel : rappel textuel si le bloc défile hors champ
  // pendant que le panneau reste ouvert). Une seule fonction, réutilisée par les deux moteurs
  // (structuré ici, legacy directement sur el.textContent) —
  // jamais deux implémentations séparées pour la même préoccupation.
  function adocBlockPreviewText(block) {
    const c = block && block.content || {};
    const raw = c.text || (Array.isArray(c.items) ? c.items.join(', ') : '')
      || (c.title) || (Array.isArray(c.headers) ? c.headers.join(' / ') : '') || '';
    const trimmed = String(raw).trim();
    return trimmed.length > 60 ? trimmed.slice(0, 60) + '…' : trimmed;
  }
  function adocEditorArt() { return window._adocArtifacts && window._adocArtifacts[window._adocWsState && window._adocWsState.storeKey]; }
  function adocEditorContext() {
    const art = adocEditorArt();
    if (!art) return null;
    const legacy = art._adocGenerationEngine === 'legacy-html';
    const st = legacy ? window._adocLegacyBlockEditState : window._adocBlockEditState;
    const el = legacy ? st.el : document.getElementById(st.blockId);
    if (!el || !el.isConnected) return null;
    return {art: art, legacy: legacy, st: st, el: el, block: legacy ? null : adocFindEditableBlock(art._adocStructuredDoc, st.blockId)};
  }
  function adocEditorMessage(message) {
    // 0B précisé — un seul .cc-block-edit-panel existe à la fois sur toute la page
    // (adocWsClearBlockSelection/adocWsClearLegacyBlockSelection le retirent avant toute
    // nouvelle sélection), sélecteur global suffisant, quel que soit son point de montage.
    const panel = document.querySelector('.cc-block-edit-panel');
    const out = panel && panel.querySelector('.cc-editor-message');
    if (out) out.textContent = message;
  }
  function adocEditorStyleCSS(style, kind) {
    const el = document.createElement('span');
    style = style || {};
    const family = style.fontFamily || adocResolveBlockFontFamily(kind, style.fontPairId);
    if (family) el.style.fontFamily = '"' + String(family).replace(/["\\\n\r]/g, '') + '"';
    const preset = ADOC_BLOCK_FONT_SIZES.find(function (s) { return s.id === style.fontSize; });
    if (preset && preset.cssValue) el.style.fontSize = preset.cssValue;
    Object.keys(ADOC_DIRECT_STYLE_FIELDS).forEach(function (key) {
      if (key === 'fontFamily' || style[key] == null || style[key] === '') return;
      let value = String(style[key]);
      if (key === 'fontSizePt') value = Math.max(6, Math.min(144, Number(value))) + 'pt';
      if (['letterSpacing', 'marginTop', 'marginBottom', 'textIndent', 'borderWidth'].includes(key)) value = Number(value) + 'px';
      if (/url\s*\(|[{}<>;]/i.test(value)) return;
      el.style.setProperty(ADOC_DIRECT_STYLE_FIELDS[key], value);
    });
    if (style.borderWidth) el.style.borderStyle = 'solid';
    return el.style.cssText;
  }
  function adocEditorReadStyle(el) {
    const style = {};
    Object.keys(ADOC_DIRECT_STYLE_FIELDS).forEach(function (key) {
      const value = el.style.getPropertyValue(ADOC_DIRECT_STYLE_FIELDS[key]);
      if (!value) return;
      if (key === 'fontFamily') style[key] = value.replace(/^['"]|['"]$/g, '');
      else if (key === 'fontSizePt') { if (value.endsWith('pt')) style[key] = parseFloat(value); else if(value.endsWith('px')) style[key]=parseFloat(value)*0.75; else {const preset=ADOC_BLOCK_FONT_SIZES.find(s=>s.cssValue===value);if(preset)style.fontSize=preset.id;} }
      else if (['letterSpacing','marginTop','marginBottom','textIndent','borderWidth','lineHeight'].includes(key)) { if (Number.isFinite(parseFloat(value))) style[key] = parseFloat(value); }
      else style[key] = value;
    });
    return style;
  }
  // Rich text is an allowlisted presentation of the plain content, never executable HTML.
  function adocEditorCleanHTML(html) {
    const source = document.createElement('template'); source.innerHTML = html || '';
    const out = document.createElement('div');
    function walk(node, parent) {
      if (node.nodeType === 3) { parent.appendChild(document.createTextNode(node.data)); return; }
      if (node.nodeType !== 1 || /^(SCRIPT|STYLE|IFRAME|OBJECT|SVG|MATH|FORM|INPUT|BUTTON|TEXTAREA)$/.test(node.tagName)) return;
      const tag = node.tagName.toLowerCase();
      if (tag === 'br') { parent.appendChild(document.createElement('br')); return; }
      const allowed = ['b','strong','i','em','u','s','strike','sub','sup','span','mark'];
      const dest = document.createElement(allowed.includes(tag) ? tag : 'span');
      const style = adocEditorReadStyle(node);
      // Inline ranges cannot acquire block geometry from pasted documents.
      ['marginTop','marginBottom','textIndent','borderWidth','borderColor'].forEach(function (k) { delete style[k]; });
      dest.style.cssText = adocEditorStyleCSS(style, 'paragraph');
      Array.from(node.childNodes).forEach(function (n) { walk(n, dest); });
      parent.appendChild(dest);
      if (['p','div','li','tr'].includes(tag) && node.nextSibling) parent.appendChild(document.createElement('br'));
    }
    Array.from(source.content.childNodes).forEach(function (n) { walk(n, out); });
    return out.innerHTML;
  }
