      if(r===0) { const body=table.tBodies[0]||table.createTBody();body.prepend(tr); } else if(action==='row-before')row.before(tr);else row.after(tr);
      adocEditorFocus(tr.querySelector('[data-cc-editor-leaf]'),false);
