    if(formats[action]) {
      const f=formats[action],scope=ctx.st.panelEl.querySelector('[data-editor-scope]').value;
      let target=scope==='block'?ctx.el:adocEditorLeafInContext(ctx)||ctx.el;
      if(scope==='selection'&&_adocEditorRange){const n=_adocEditorRange.commonAncestorContainer;target=n.nodeType===1?n:n.parentElement;}
      const computed=getComputedStyle(target);
      if(f[0]==='textDecoration'){const parts=computed.textDecorationLine.split(' ').filter(p=>p!=='none'&&p!==f[1]);if(!computed.textDecorationLine.includes(f[1]))parts.push(f[1]);adocEditorApplyStyle(f[0],parts.join(' ')||'none');}
      else adocEditorApplyStyle(f[0],computed[f[0]]===f[1]?f[2]:f[1]);return;
    }
